export const BIOLOGY_TOPICS: Record<string, Topic> = {"bio-living-characteristics":{id:"bio-living-characteristics",title:"Characteristics of Living Organisms",chapterId:"living-world",estimatedReadTimeMinutes:10,importanceWeight:"Core Concept",summary:"Growth, reproduction, metabolism, cellular organisation, and consciousness as defining features of life.",notes:{learn:["Growth and reproduction are characteristic features of living organisms, but they are NOT defining properties because non-living objects can grow (accumulation of mass) and some living organisms do not reproduce (mules, sterile worker bees).","Metabolism, Cellular Organisation, and Consciousness are ABSOLUTE DEFINING PROPERTIES of all living organisms without exception."],keyConcepts:["Defining Properties: Metabolism, Cellular Organisation, Consciousness.","Non-defining Properties: Growth, Reproduction."],formulas:[],neetImportantPoints:["Consciousness is the most obvious and technically complicated defining feature of all living organisms."],commonConfusions:[{commonConfusion:"Growth is a defining property of living organisms.",correctFact:"Growth is NOT a defining property because mountains and sand dunes also increase in mass.",whyItMattersForNEET:"Direct true/false statement question in NEET."}],quickRevision:["Defining: Metabolism, Cellular Org, Consciousness","Non-defining: Growth, Reproduction"]},pyqs:[]},"bio-taxonomy-hierarchy":{id:"bio-taxonomy-hierarchy",title:"Taxonomy, Systematics & Binomial Nomenclature",chapterId:"living-world",estimatedReadTimeMinutes:12,importanceWeight:"High Yield",summary:"Rules of binomial nomenclature (Linnaeus), taxonomic categories (Species to Kingdom), and herbarium/botanical gardens.",notes:{learn:["Binomial Nomenclature (Carolus Linnaeus): Generic name capitalized, specific epithet lowercase, printed in italics or underlined if handwritten.","Taxonomic Hierarchy: Kingdom > Phylum/Division > Class > Order > Family > Genus > Species."],keyConcepts:["Species is the lowest basic unit of taxonomy.","As we go higher from Species to Kingdom, the number of common characteristics DECREASES."],formulas:[],neetImportantPoints:["Housefly: Musca domestica, Family Muscidae, Order Diptera, Class Insecta, Phylum Arthropoda."],commonConfusions:[{commonConfusion:"Common characteristics increase going from Species to Kingdom.",correctFact:"Common characteristics DECREASE as you move up from Species to Kingdom.",whyItMattersForNEET:"High-yield conceptual question."}],quickRevision:["Binomial: Genus species","Common features decrease upwards"]},pyqs:[]},"eukaryotic-organelles":{id:"eukaryotic-organelles",title:"Eukaryotic Cell Organelles & Endomembrane System",chapterId:"cell-unit-of-life",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Endomembrane system (ER, Golgi, Lysosome, Vacuole), Mitochondria, Chloroplasts, and Ribosomes.",notes:{learn:["The Endomembrane System includes ER, Golgi apparatus, Lysosomes, and Vacuoles because their functions are coordinated.","Mitochondria and Chloroplasts are semi-autonomous organelles containing their own 70S ribosomes and circular dsDNA."],keyConcepts:["Mitochondria & Chloroplasts have 70S ribosomes.","Golgi apparatus is the chief site of glycoprotein and glycolipid formation."],formulas:[],neetImportantPoints:["Lysosomes contain hydrolytic enzymes (hydrolases) active at acidic pH (~5.0)."],commonConfusions:[{commonConfusion:"Mitochondria contain 80S ribosomes.",correctFact:"Mitochondria contain 70S prokaryotic-type ribosomes inside their matrix.",whyItMattersForNEET:"Mitochondria organelle question."}],quickRevision:["Endomembrane = ER + Golgi + Lysosome + Vacuole","Mitochondria/Chloroplast = 70S + circular DNA"]},pyqs:[]},"human-respiratory-system":{id:"human-respiratory-system",title:"Human Respiratory System & Mechanism of Breathing",chapterId:"breathing-exchange-gases",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Anatomy of respiratory tract, alveoli gas exchange surface, diaphragm and intercostal muscle breathing mechanism.",notes:{learn:["Inspiration is an ACTIVE process initiated by contraction of diaphragm and external intercostal muscles.","Expiration is a PASSIVE process under normal restful conditions, caused by relaxation of diaphragm and intercostals."],keyConcepts:["Diaphragm contraction increases thoracic volume antero-posteriorly.","External intercostals increase thoracic volume dorso-ventrally."],formulas:[],neetImportantPoints:["Alveoli walls consist of thin squamous epithelium optimal for simple diffusion of O2 and CO2."],commonConfusions:[{commonConfusion:"Normal expiration requires muscle contraction.",correctFact:"Normal expiration is passive due to elastic recoil of lungs; forced expiration requires abdominal muscles.",whyItMattersForNEET:"Assertion-Reason question in NEET."}],quickRevision:["Inspiration = Active (Diaphragm contracts)","Expiration = Passive (Recoil)"]},pyqs:[]},"gas-transport-mechanisms":{id:"gas-transport-mechanisms",title:"Lung Volumes & Transport of O2 and CO2",chapterId:"breathing-exchange-gases",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Tidal volume, IRV, ERV, RV, Oxygen dissociation curve, Bohr effect, and CO2 transport forms.",notes:{learn:["Tidal Volume (TV) = ~500 mL. Vital Capacity (VC) = ERV + TV + IRV (~3500-4500 mL).","Residual Volume (RV) = ~1100-1200 mL. RV cannot be measured using a simple spirometer.","Oxygen Dissociation Curve is SIGMOID. Right shift occurs with high pCO2, high H+ (low pH), high temperature (Bohr Effect)."],keyConcepts:["CO2 Transport: 70% as Bicarbonate ions (HCO3-), 20-25% as Carbamino-hemoglobin, 7% dissolved in plasma.","O2 Transport: 97% as Oxyhemoglobin in RBCs, 3% dissolved in plasma."],formulas:[{title:"Vital Capacity Formula",formula:"VC = ERV + TV + IRV"}],neetImportantPoints:["Residual Volume (RV) and Functional Residual Capacity (FRC) CANNOT be measured by spirometer."],commonConfusions:[{commonConfusion:"High pH causes right shift of O2 dissociation curve.",correctFact:"LOW pH (acidic) and HIGH pCO2 cause right shift (unloading of O2 to tissues).",whyItMattersForNEET:"Guaranteed NEET curve shift question."}],quickRevision:["TV = 500 mL","RV cannot be measured by spirometer","Right shift = Low pH, High pCO2"]},pyqs:[]},"bio-respiratory-regulation-disorders":{id:"bio-respiratory-regulation-disorders",title:"Regulation of Respiration & Respiratory Disorders",chapterId:"breathing-exchange-gases",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Neural and chemical regulation of respiration, respiratory rhythm centre, pneumotaxic centre, asthma, emphysema, occupational disorders.",notes:{learn:["Medullary rhythm centre maintains respiratory rhythm; pneumotaxic centre in pons reduces inspiration duration.","Chemosensitive area is sensitive to CO2 and H+ ions; O2 plays a negligible role in regulation.","Emphysema is caused by cigarette smoking causing alveolar wall damage; Asthma is bronchial inflammation with wheezing."],keyConcepts:["Oxygen plays a negligible role in respiratory rhythm regulation.","Cigarette smoking causes Emphysema by destroying alveolar septa and surface area."],formulas:[],neetImportantPoints:["Aortic arch and carotid artery chemoreceptors detect CO2 and H+ concentrations."],commonConfusions:[{commonConfusion:"Oxygen is the primary stimulus for respiratory regulation.",correctFact:"CO2 and H+ ions (pH) are the primary chemical stimuli; O2 plays a negligible role.",whyItMattersForNEET:"Frequently asked NEET trap question."}],quickRevision:["Rhythm centre = Medulla, Pneumotaxic = Pons, CO2/H+ = Main chemical triggers"]},pyqs:[]},"bio-kingdom-monera":{id:"bio-kingdom-monera",title:"Kingdom Monera (Bacteria & Archaebacteria)",chapterId:"biological-classification",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Structure of prokaryotic cell, archaebacteria, cyanobacteria, heterotrophic bacteria, and mycoplasma.",notes:{learn:["Bacteria are sole members of Kingdom Monera. Archaebacteria live in extreme environments (Methanogens in gut of ruminants, Halophiles in salty areas, Thermoacidophiles in hot springs).","Cyanobacteria (Blue-green algae) have chlorophyll a and fix atmospheric nitrogen in specialized cells called Heterocysts (e.g. Nostoc, Anabaena). Mycoplasma LACK a cell wall and are smallest living cells operating anaerobically."],keyConcepts:["Bacteria are sole members of Kingdom Monera. Archaebacteria live in extreme environments (Methanogens in gut of ruminants, Halophiles in salty areas, Thermoacidophiles in hot springs)."],formulas:[{title:"Nitrogen Fixation Cell",formula:"Heterocysts in Nostoc / Anabaena"}],neetImportantPoints:["Mycoplasma are completely devoid of a cell wall and are resistant to penicillin."],commonConfusions:[{commonConfusion:"Confusing terms in Kingdom Monera (Bacteria & Archaebacteria).",correctFact:"Memorize exact NCERT examples and diagrams for Kingdom Monera (Bacteria & Archaebacteria).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Heterocysts in Nostoc, Mycoplasma lacks cell wall"]},pyqs:[]},"bio-kingdom-protista":{id:"bio-kingdom-protista",title:"Kingdom Protista (Chrysophytes to Protozoans)",chapterId:"biological-classification",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Diatoms, Dinoflagellates, Euglenoids, Slime moulds, and Protozoans.",notes:{learn:["Chrysophytes include Diatoms (indestructible cell walls embedded with silica forming Diatomaceous Earth) and Desmids.","Dinoflagellates cause Red Tides (Gonyaulax) producing toxins. Euglenoids (Euglena) have protein-rich layer called Pellicle making body flexible."],keyConcepts:["Chrysophytes include Diatoms (indestructible cell walls embedded with silica forming Diatomaceous Earth) and Desmids."],formulas:[{title:"Diatom Wall Feature",formula:"Silicified frustule implies Diatomaceous earth used in polishing & filtration"}],neetImportantPoints:["Entamoeba histolytica is a protozoan causing amoebic dysentery; Plasmodium causes malaria."],commonConfusions:[{commonConfusion:"Confusing terms in Kingdom Protista (Chrysophytes to Protozoans).",correctFact:"Memorize exact NCERT examples and diagrams for Kingdom Protista (Chrysophytes to Protozoans).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Diatoms = silica cell wall, Gonyaulax = red tide"]},pyqs:[]},"bio-kingdom-fungi":{id:"bio-kingdom-fungi",title:"Kingdom Fungi (Classes & Reproduction)",chapterId:"biological-classification",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Phycomycetes, Ascomycetes, Basidiomycetes, and Deuteromycetes features and examples.",notes:{learn:["Fungal cell walls are made of Chitin and polysaccharides. Body consists of long slender thread-like hyphae forming Mycelium.","Phycomycetes (Algal fungi, e.g. Mucor, Rhizopus, Albugo) have ASEPTATE coenocytic mycelium. Ascomycetes (Sac fungi, e.g. Penicillium, Yeast, Aspergillus, Neurospora) produce endogenous ascospores."],keyConcepts:["Fungal cell walls are made of Chitin and polysaccharides. Body consists of long slender thread-like hyphae forming Mycelium."],formulas:[{title:"Fungi Classes Summary",formula:"Phycomycetes (aseptate)|Ascomycetes (sac)|Basidiomycetes (club)|Deuteromycetes (imperfect)"}],neetImportantPoints:["Deuteromycetes are known as Imperfect Fungi because sexual stage is absent or unknown (e.g. Alternaria, Colletotrichum, Trichoderma)."],commonConfusions:[{commonConfusion:"Confusing terms in Kingdom Fungi (Classes & Reproduction).",correctFact:"Memorize exact NCERT examples and diagrams for Kingdom Fungi (Classes & Reproduction).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Deuteromycetes = Imperfect fungi, Ascomycetes = Sac fungi"]},pyqs:[]},"bio-viruses-viroids-lichens":{id:"bio-viruses-viroids-lichens",title:"Viruses, Viroids, Prions & Lichens",chapterId:"biological-classification",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Acellular organisms, capsomeres, viroids (free RNA), prions (folded proteins), lichens.",notes:{learn:["Viruses are non-cellular obligate parasites with genetic material (DNA or RNA) enclosed in protein coat (capsid made of capsomeres).","Viroids discovered by T.O. Diener (1971) cause Potato Spindle Tuber Disease; contain free low molecular weight RNA WITHOUT protein coat. Prions cause Mad Cow disease (BSE) and Cr-Jacob disease."],keyConcepts:["Viruses are non-cellular obligate parasites with genetic material (DNA or RNA) enclosed in protein coat (capsid made of capsomeres)."],formulas:[{title:"Lichen Symbiosis",formula:"Lichen = Phycobiont (algae, autotrophic) + Mycobiont (fungi, heterotrophic)"}],neetImportantPoints:["Lichens do NOT grow in polluted areas and serve as excellent SO2 pollution indicators."],commonConfusions:[{commonConfusion:"Confusing terms in Viruses, Viroids, Prions & Lichens.",correctFact:"Memorize exact NCERT examples and diagrams for Viruses, Viroids, Prions & Lichens.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Viroids = free RNA no coat, Lichens = SO2 pollution indicator"]},pyqs:[]},"bio-algae-chlorophyceae":{id:"bio-algae-chlorophyceae",title:"Algae - Chlorophyceae, Phaeophyceae & Rhodophyceae",chapterId:"plant-kingdom",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Green algae (Chlorophyceae), Brown algae (Phaeophyceae), Red algae (Rhodophyceae) comparison.",notes:{learn:["Chlorophyceae: Chlorophyll a, b; Stored food = Starch in Pyrenoids (protein surrounded by starch); Cell wall = Cellulose.","Phaeophyceae (Brown): Chlorophyll a, c, Fucoxanthin; Stored food = Laminarin / Mannitol; Algin in cell wall. Rhodophyceae (Red): Chlorophyll a, d, r-Phycoerythrin; Stored food = Floridean starch (similar to amylopectin and glycogen); Agar-agar obtained from Gelidium and Gracilaria."],keyConcepts:["Chlorophyceae: Chlorophyll a, b; Stored food = Starch in Pyrenoids (protein surrounded by starch); Cell wall = Cellulose."],formulas:[{title:"Algal Storage Comparison",formula:"Green: Starch|Brown: Laminarin/Mannitol|Red: Floridean starch"}],neetImportantPoints:["Algin is hydrocolloid from Brown algae; Carrageen is hydrocolloid from Red algae."],commonConfusions:[{commonConfusion:"Confusing terms in Algae - Chlorophyceae, Phaeophyceae & Rhodophyceae.",correctFact:"Memorize exact NCERT examples and diagrams for Algae - Chlorophyceae, Phaeophyceae & Rhodophyceae.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Red algae = Floridean starch + r-Phycoerythrin"]},pyqs:[]},"bio-bryophytes-pteridophytes":{id:"bio-bryophytes-pteridophytes",title:"Bryophytes & Pteridophytes",chapterId:"plant-kingdom",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Liverworts, Mosses, Vascular cryptogams, Homosporous vs Heterosporous pteridophytes.",notes:{learn:["Bryophytes (Amphibians of plant kingdom): Gametophyte is dominant independent green phase; Sporophyte is dependent on gametophyte for nutrition (e.g., Marchantia, Sphagnum peat moss).","Pteridophytes (First terrestrial vascular plants with Xylem & Phloem): Sporophyte is dominant. Heterosporous pteridophytes (Selaginella, Salvinia) produce micro and megaspores, leading towards seed habit."],keyConcepts:["Bryophytes (Amphibians of plant kingdom): Gametophyte is dominant independent green phase; Sporophyte is dependent on gametophyte for nutrition (e.g., Marchantia, Sphagnum peat moss)."],formulas:[{title:"Heterosporous Pteridophytes",formula:"Selaginella and Salvinia produce two types of spores (Heterospory)"}],neetImportantPoints:["Sphagnum moss produces peat used as fuel and packing material for trans-shipment of living material due to water holding capacity."],commonConfusions:[{commonConfusion:"Confusing terms in Bryophytes & Pteridophytes.",correctFact:"Memorize exact NCERT examples and diagrams for Bryophytes & Pteridophytes.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Bryophytes = Gametophyte dominant, Selaginella/Salvinia = Heterosporous"]},pyqs:[]},"bio-gymnosperms-alternation":{id:"bio-gymnosperms-alternation",title:"Gymnosperms & Plant Life Cycles",chapterId:"plant-kingdom",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Naked seeds, Cycas, Pinus, mycorrhiza, coralloid roots, and life cycle patterns.",notes:{learn:["Gymnosperms have naked ovules not enclosed by ovary wall. Pinus roots have fungal association (Mycorrhiza); Cycas roots have N2-fixing Cyanobacteria (Coralloid roots).","Pinus is monoecious (male and female cones on same tree); Cycas is dioecious (male and female cones on separate trees)."],keyConcepts:["Gymnosperms have naked ovules not enclosed by ovary wall. Pinus roots have fungal association (Mycorrhiza); Cycas roots have N2-fixing Cyanobacteria (Coralloid roots)."],formulas:[{title:"Coralloid Roots",formula:"Cycas coralloid roots associated with Anabaena / Nostoc (Cyanobacteria)"}],neetImportantPoints:["Gymnosperms lack xylem vessels (except Gnetales) and companion cells in phloem (possess albuminous cells)."],commonConfusions:[{commonConfusion:"Confusing terms in Gymnosperms & Plant Life Cycles.",correctFact:"Memorize exact NCERT examples and diagrams for Gymnosperms & Plant Life Cycles.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Cycas = Coralloid roots (N2-fixing), Pinus = Mycorrhiza"]},pyqs:[]},"bio-non-chordates-porifera-annelida":{id:"bio-non-chordates-porifera-annelida",title:"Non-Chordates I - Porifera to Annelida",chapterId:"animal-kingdom",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Porifera (sponges/water canal), Cnidaria (stinging cells/metagenesis), Ctenophora, Platyhelminthes, Aschelminthes, Annelida.",notes:{learn:["Porifera: Cellular level, Ostia/Osculum water canal system lined by Choanocytes (collar cells). Spongilla (freshwater), Sycon, Euspongia.","Cnidaria: Tissue level, Cnidoblasts/Cnidocytes. Metagenesis (alternation of generations between Polyp and Medusa) shown by Obelia. Physalia (Portuguese man-of-war)."],keyConcepts:["Porifera: Cellular level, Ostia/Osculum water canal system lined by Choanocytes (collar cells). Spongilla (freshwater), Sycon, Euspongia."],formulas:[{title:"Cnidaria Metagenesis",formula:"Polyp (asexual) implies|Medusa (sexual) in Obelia"}],neetImportantPoints:["Aschelminthes (Roundworms, e.g. Ascaris, Wuchereria) are Pseudocoelomate with complete alimentary canal with muscular pharynx."],commonConfusions:[{commonConfusion:"Confusing terms in Non-Chordates I - Porifera to Annelida.",correctFact:"Memorize exact NCERT examples and diagrams for Non-Chordates I - Porifera to Annelida.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Porifera = Choanocytes, Cnidaria = Metagenesis (Obelia), Aschelminthes = Pseudocoelomate"]},pyqs:[]},"bio-non-chordates-arthropoda-hemichordata":{id:"bio-non-chordates-arthropoda-hemichordata",title:"Non-Chordates II - Arthropoda to Hemichordata",chapterId:"animal-kingdom",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Arthropoda (chitinous exoskeleton/jointed appendages), Mollusca, Echinodermata, Hemichordata.",notes:{learn:["Arthropoda: Largest phylum, chitinous exoskeleton, Malpighian tubules for excretion. Economically important: Apis, Bombyx, Laccifer. Vector: Anopheles, Culex, Aedes. Living fossil: Limulus (King crab).","Echinodermata: Radial symmetry in adult, bilateral in larva; Water Vascular System for locomotion and food capture. Hemichordata: Balanoglossus with Stomochord in collar region."],keyConcepts:["Arthropoda: Largest phylum, chitinous exoskeleton, Malpighian tubules for excretion. Economically important: Apis, Bombyx, Laccifer. Vector: Anopheles, Culex, Aedes. Living fossil: Limulus (King crab)."],formulas:[{title:"Echinodermata Symmetry",formula:"Adults: Radial symmetry|Larvae: Bilateral symmetry"}],neetImportantPoints:["Mollusca is second largest phylum; soft body enclosed in calcareous shell with radula (rasping organ for feeding)."],commonConfusions:[{commonConfusion:"Confusing terms in Non-Chordates II - Arthropoda to Hemichordata.",correctFact:"Memorize exact NCERT examples and diagrams for Non-Chordates II - Arthropoda to Hemichordata.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Arthropoda = Malpighian tubules, Echinodermata = Water vascular system"]},pyqs:[]},"bio-chordates-classes":{id:"bio-chordates-classes",title:"Chordates & Vertebrate Classes",chapterId:"animal-kingdom",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Chordate hallmarks (notochord, dorsal hollow nerve cord, pharyngeal slits) and classes Cyclostomata to Mammalia.",notes:{learn:["Fundamental Chordate characters: Notochord, Dorsal hollow single nerve cord, Paired pharyngeal gill slits, Post-anal tail.","Cyclostomata (jawless, e.g., Petromyzon lamprey - spawning in freshwater then die). Chondrichthyes (cartilaginous fish, placoid scales, ventral mouth, air bladder absent e.g. Scoliodon, Torpedo electric ray, Trygon sting ray). Osteichthyes (bony fish, cycloid scales, terminal mouth, operculum and air bladder present)."],keyConcepts:["Fundamental Chordate characters: Notochord, Dorsal hollow single nerve cord, Paired pharyngeal gill slits, Post-anal tail."],formulas:[{title:"Fish Differences",formula:"Chondrichthyes: Air bladder absent (must swim constantly)|Osteichthyes: Air bladder present"}],neetImportantPoints:["Amphibia (3-chambered heart, moist skin without scales, tympanum represents ear). Aves (pneumatic long bones, air sacs connected to lungs for respiration). Mammals (mammary glands, hair, 4-chambered heart). Oviparous mammal: Ornithorhynchus (Platypus)."],commonConfusions:[{commonConfusion:"Confusing terms in Chordates & Vertebrate Classes.",correctFact:"Memorize exact NCERT examples and diagrams for Chordates & Vertebrate Classes.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Chondrichthyes = No air bladder, Aves = Pneumatic bones, Platypus = Oviparous mammal"]},pyqs:[]},"bio-root-stem-leaf-morphology":{id:"bio-root-stem-leaf-morphology",title:"Root, Stem & Leaf Modifications",chapterId:"morphology-flowering-plants",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Tap/fibrous/adventitous roots, stem modifications (tendril, thorn, cladode, offset), phyllotaxy.",notes:{learn:["Root modifications: Taproot of carrot/turnip (storage); Prop roots of Banyan; Stilt roots of Maize/Sugarcane; Pneumatophores of Rhizophora (respiratory roots in swamps).","Stem modifications: Stem tendril (Cucumber, Pumpkin); Thorns (Bougainvillea, Citrus - modified axillary buds for defense); Offset (Eichhornia/Pistia); Phylloclade (flattened photosynthetic stem in Opuntia)."],keyConcepts:["Root modifications: Taproot of carrot/turnip (storage); Prop roots of Banyan; Stilt roots of Maize/Sugarcane; Pneumatophores of Rhizophora (respiratory roots in swamps)."],formulas:[{title:"Phyllotaxy Types",formula:"Alternate (Mustard)|Opposite (Calotropis, Guava)|Whorled (Alstonia)"}],neetImportantPoints:["In Australian Acacia, leaves are short-lived and petiole expands to become green photosynthetic Phyllode."],commonConfusions:[{commonConfusion:"Confusing terms in Root, Stem & Leaf Modifications.",correctFact:"Memorize exact NCERT examples and diagrams for Root, Stem & Leaf Modifications.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Pneumatophores in Rhizophora, Opuntia stem = Phylloclade"]},pyqs:[]},"bio-flower-inflorescence-placentation":{id:"bio-flower-inflorescence-placentation",title:"Inflorescence, Placentation & Fruit",chapterId:"morphology-flowering-plants",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Racemose vs Cymose inflorescence, ovary position (Epigynous/Perigynous/Hypogynous), placentation types.",notes:{learn:["Inflorescence: Racemose (main axis continues to grow, acropetal succession); Cymose (main axis terminates in flower, basipetal).","Ovary Position: Hypogynous (Superior ovary - Mustard, China rose, Brinjal); Perigynous (Half-inferior - Plum, Rose, Peach); Epigynous (Inferior ovary - Guava, Cucumber, Ray florets of sunflower)."],keyConcepts:["Inflorescence: Racemose (main axis continues to grow, acropetal succession); Cymose (main axis terminates in flower, basipetal)."],formulas:[{title:"Placentation Types",formula:"Marginal (Pea)|Axile (China rose, Tomato)|Parietal (Mustard, Argemone)|Free Central (Dianthus, Primrose)|Basal (Sunflower, Marigold)"}],neetImportantPoints:["Parietal placentation features a false septum called Replum (in Mustard/Bricaceae)."],commonConfusions:[{commonConfusion:"Confusing terms in Inflorescence, Placentation & Fruit.",correctFact:"Memorize exact NCERT examples and diagrams for Inflorescence, Placentation & Fruit.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Free Central = Dianthus/Primrose, Basal = Sunflower"]},pyqs:[]},"bio-plant-families":{id:"bio-plant-families",title:"Plant Families - Solanaceae, Fabaceae & Others",chapterId:"morphology-flowering-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Floral characters, floral diagrams, and economic importance of key plant families.",notes:{learn:["Fabaceae: Diadelphous stamens (9)+1, papilionaceous corolla (vexillum, wings, keel), marginal placentation (e.g. Gram, Arhar, Moong, Glycine max soybean, Indigofera).","Solanaceae (Potato family): Epipetalous stamens, swollen placenta with axile placentation, oblique ovary (e.g. Solanum tuberosum, Tomato, Brinjal, Chilli, Belladonna, Ashwagandha, Tobacco)."],keyConcepts:["Fabaceae: Diadelphous stamens (9)+1, papilionaceous corolla (vexillum, wings, keel), marginal placentation (e.g. Gram, Arhar, Moong, Glycine max soybean, Indigofera)."],formulas:[{title:"Fabaceae Floral Formula",formula:"% mathbin{dagger} K_{(5)} C_{1+2+(2)} A_{(9)+1} G_1"}],neetImportantPoints:["Brassicaceae (Cruciferae): Tetradynamous stamens (2+4), parietal placentation with replum."],commonConfusions:[{commonConfusion:"Confusing terms in Plant Families - Solanaceae, Fabaceae & Others.",correctFact:"Memorize exact NCERT examples and diagrams for Plant Families - Solanaceae, Fabaceae & Others.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Fabaceae = Diadelphous (9)+1, Solanaceae = Swollen placenta"]},pyqs:[]},"bio-meristematic-permanent-tissues":{id:"bio-meristematic-permanent-tissues",title:"Meristematic & Permanent Tissues",chapterId:"anatomy-flowering-plants",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Apical/intercalary/lateral meristems, parenchyma, collenchyma, sclerenchyma, xylem, phloem.",notes:{learn:["Meristems: Apical & Intercalary (primary meristems, increase length); Lateral meristems (Vascular cambium & Cork cambium, increase girth/secondary growth).","Collenchyma has pectin deposits at corners, provides mechanical support to growing young stems. Sclerenchyma consists of dead sclereids and fibers with lignified walls."],keyConcepts:["Meristems: Apical & Intercalary (primary meristems, increase length); Lateral meristems (Vascular cambium & Cork cambium, increase girth/secondary growth)."],formulas:[{title:"Xylem & Phloem Components",formula:"Xylem: Tracheids, Vessels, Xylem Fibers, Xylem Parenchyma (only living component)"}],neetImportantPoints:["Gymnosperms lack xylem vessels and sieve tubes/companion cells in phloem."],commonConfusions:[{commonConfusion:"Confusing terms in Meristematic & Permanent Tissues.",correctFact:"Memorize exact NCERT examples and diagrams for Meristematic & Permanent Tissues.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Collenchyma has pectin at corners, Gymnosperms lack vessels"]},pyqs:[]},"bio-root-stem-leaf-anatomy":{id:"bio-root-stem-leaf-anatomy",title:"Anatomy of Dicot & Monocot Root, Stem & Leaf",chapterId:"anatomy-flowering-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Internal vascular organization differences in dicot vs monocot roots, stems, and leaves.",notes:{learn:["Root: Dicot root has radial vascular bundles with exarch xylem, 2-4 xylem bundles, small pith. Monocot root has POLYARCH xylem (> 6 bundles) and LARGE well-developed pith.","Stem: Dicot stem has ring arrangement of vascular bundles (conjoint, collateral, OPEN with cambium). Monocot stem has SCATTERED vascular bundles (conjoint, collateral, CLOSED without cambium) surrounded by sclerenchymatous bundle sheath."],keyConcepts:["Root: Dicot root has radial vascular bundles with exarch xylem, 2-4 xylem bundles, small pith. Monocot root has POLYARCH xylem (> 6 bundles) and LARGE well-developed pith."],formulas:[{title:"Monocot vs Dicot Stem",formula:"Dicot Stem: Ring of open bundles|Monocot Stem: Scattered closed bundles"}],neetImportantPoints:["Isobilateral leaf (Monocot) has bulliform cells in upper epidermis for rolling of leaves during water stress."],commonConfusions:[{commonConfusion:"Confusing terms in Anatomy of Dicot & Monocot Root, Stem & Leaf.",correctFact:"Memorize exact NCERT examples and diagrams for Anatomy of Dicot & Monocot Root, Stem & Leaf.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Monocot root = Polyarch + Large pith, Monocot stem = Scattered bundles"]},pyqs:[]},"bio-secondary-growth":{id:"bio-secondary-growth",title:"Secondary Growth in Dicot Stem & Root",chapterId:"anatomy-flowering-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Vascular cambium ring formation, spring wood vs autumn wood, heartwood vs sapwood, cork cambium (phellogen).",notes:{learn:["Vascular cambium forms continuous ring (intrafascicular + interfascicular cambium). Cuts off MORE secondary xylem towards inside than secondary phloem outside.","Spring wood (early wood) has wide vessels; Autumn wood (late wood) has narrow vessels. Annual ring = Spring wood + Autumn wood (indicates age of tree - Dendrochronology)."],keyConcepts:["Vascular cambium forms continuous ring (intrafascicular + interfascicular cambium). Cuts off MORE secondary xylem towards inside than secondary phloem outside."],formulas:[{title:"Periderm Components",formula:"Periderm = Phellogen (Cork Cambium) + Phellem (Cork) + Phelloderm (Secondary Cortex)"}],neetImportantPoints:["Heartwood is dark, durable, non-conducting inner secondary xylem resistant to microbes; Sapwood is lighter outer conducting region."],commonConfusions:[{commonConfusion:"Confusing terms in Secondary Growth in Dicot Stem & Root.",correctFact:"Memorize exact NCERT examples and diagrams for Secondary Growth in Dicot Stem & Root.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Periderm = Phellogen + Phellem + Phelloderm, Annual ring = 1 year age"]},pyqs:[]},"bio-animal-tissues":{id:"bio-animal-tissues",title:"Animal Tissues - Epithelial, Connective & Neural",chapterId:"structural-org-animals",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Squamous, cuboidal, columnar, ciliated epithelium, dense/loose connective tissue, cartilage, bone, muscle types.",notes:{learn:["Squamous epithelium (diffusion boundary): Blood vessels, lung alveoli. Cuboidal (secretion/absorption with microvilli): Duct of glands, PCT of nephron. Ciliated: Fallopian tubes, bronchioles.","Connective Tissues: Areolar & Adipose (loose); Tendons (connects muscle to bone) and Ligaments (connects bone to bone) (dense regular)."],keyConcepts:["Squamous epithelium (diffusion boundary): Blood vessels, lung alveoli. Cuboidal (secretion/absorption with microvilli): Duct of glands, PCT of nephron. Ciliated: Fallopian tubes, bronchioles."],formulas:[{title:"Epithelium Distribution",formula:"PCT of Nephron: Cuboidal with microvilli|Fallopian tube: Ciliated columnar"}],neetImportantPoints:["Tight junctions prevent leaking across tissues; Adhering junctions cement neighbors; Gap junctions facilitate rapid ion communication."],commonConfusions:[{commonConfusion:"Confusing terms in Animal Tissues - Epithelial, Connective & Neural.",correctFact:"Memorize exact NCERT examples and diagrams for Animal Tissues - Epithelial, Connective & Neural.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Tendon = Muscle to Bone, Ligament = Bone to Bone"]},pyqs:[]},"bio-cockroach-frog-anatomy":{id:"bio-cockroach-frog-anatomy",title:"Cockroach & Frog Morphology & Systems",chapterId:"structural-org-animals",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Periplaneta americana morphology, alimentary canal, Malpighian tubules, frog digestive and urogenital systems.",notes:{learn:["Cockroach (Periplaneta americana): Exoskeleton made of chitinous sclerites (tergites dorsal, sternites ventral). Head bears compound eyes (2000 ommatidia - mosaic vision).","Alimentary canal: Mouth -> Pharynx -> Oesophagus -> Crop (storage) -> Gizzard (grinding with 6 chitinous teeth) -> Midgut -> Hindgut. Hepatic caeca (6-8) at foregut-midgut junction secrete digestive juice. Malpighian tubules (100-150) at midgut-hindgut junction excrete uric acid (Uricotelic)."],keyConcepts:["Cockroach (Periplaneta americana): Exoskeleton made of chitinous sclerites (tergites dorsal, sternites ventral). Head bears compound eyes (2000 ommatidia - mosaic vision)."],formulas:[{title:"Cockroach Excretory & Digestive",formula:"Hepatic caeca (6-8) at Foregut-Midgut|Malpighian tubules (100-150) at Midgut-Hindgut"}],neetImportantPoints:["Frog (Rana tigrina): Poikilotherm, cutaneous & pulmonary respiration, 3-chambered heart (2 atria + 1 ventricle), mesorchium suspends testes."],commonConfusions:[{commonConfusion:"Confusing terms in Cockroach & Frog Morphology & Systems.",correctFact:"Memorize exact NCERT examples and diagrams for Cockroach & Frog Morphology & Systems.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Cockroach Gizzard has 6 chitinous teeth, Uricotelic excretion"]},pyqs:[]},"bio-cell-theory-prokaryotes":{id:"bio-cell-theory-prokaryotes",title:"Cell Theory & Prokaryotic Cell Structure",chapterId:"cell-unit-of-life",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Cell theory (Schleiden, Schwann, Virchow), bacterial cell envelope, mesosomes, inclusion bodies.",notes:{learn:["Cell Theory formulated by Schleiden & Schwann; modified by Rudolf Virchow (1855) adding 'Omnis cellula-e-cellula' (all cells arise from pre-existing cells).","Prokaryotes: Cell envelope consists of Glycocalyx (Slime layer or Capsule), Cell Wall, and Plasma Membrane. Mesosome is plasma membrane infolding involved in respiration, cell wall synthesis, and DNA replication."],keyConcepts:["Cell Theory formulated by Schleiden & Schwann; modified by Rudolf Virchow (1855) adding 'Omnis cellula-e-cellula' (all cells arise from pre-existing cells)."],formulas:[{title:"Prokaryotic Mesosome Function",formula:"Mesosome = Plasma membrane infolding (analogous to mitochondria in respiration)"}],neetImportantPoints:["Gram-positive bacteria retain crystal violet stain due to thick peptidoglycan cell wall; Gram-negative lose stain."],commonConfusions:[{commonConfusion:"Confusing terms in Cell Theory & Prokaryotic Cell Structure.",correctFact:"Memorize exact NCERT examples and diagrams for Cell Theory & Prokaryotic Cell Structure.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Virchow = Omnis cellula-e-cellula, Mesosome = respiration"]},pyqs:[]},"bio-nucleus-chromosomes":{id:"bio-nucleus-chromosomes",title:"Nucleus, Chromatin & Endomembrane System",chapterId:"cell-unit-of-life",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Structure of nucleus, nucleolus, chromatin, ER, Golgi apparatus, lysosomes, vacuoles, mitochondria, plastids.",notes:{learn:["Endomembrane System includes ER, Golgi complex, Lysosomes, and Vacuoles (functions are coordinated). Mitochondria and Chloroplasts are NOT part of endomembrane system!","Golgi apparatus modifies and packages proteins received from RER. Lysosomes contain hydrolytic enzymes (hydrolases) active at acidic pH."],keyConcepts:["Endomembrane System includes ER, Golgi complex, Lysosomes, and Vacuoles (functions are coordinated). Mitochondria and Chloroplasts are NOT part of endomembrane system!"],formulas:[{title:"Endomembrane System Components",formula:"Endomembrane = ER + Golgi + Lysosome + Vacuole (Mitochondria & Chloroplast excluded!)"}],neetImportantPoints:["Centromere position: Metacentric (middle), Sub-metacentric (slightly off-center), Acrocentric (near end), Telocentric (terminal)."],commonConfusions:[{commonConfusion:"Confusing terms in Nucleus, Chromatin & Endomembrane System.",correctFact:"Memorize exact NCERT examples and diagrams for Nucleus, Chromatin & Endomembrane System.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Mitochondria/Chloroplast NOT in endomembrane system"]},pyqs:[]},"bio-carbohydrates-lipids-proteins":{id:"bio-carbohydrates-lipids-proteins",title:"Biomolecules - Primary & Secondary Metabolites",chapterId:"biomolecules-bio",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Primary vs secondary metabolites, glycosidic/peptide/phosphodiester bonds, protein structure levels.",notes:{learn:["Primary metabolites have direct roles in physiological processes (glucose, amino acids). Secondary metabolites (alkaloids e.g. morphine, terpenoids, toxins e.g. ricin, lectins e.g. concanavalin A).","Lipids are NOT strictly macromolecules because molecular weight is < 800 Da, but reside in acid-insoluble fraction due to vesicle formation."],keyConcepts:["Primary metabolites have direct roles in physiological processes (glucose, amino acids). Secondary metabolites (alkaloids e.g. morphine, terpenoids, toxins e.g. ricin, lectins e.g. concanavalin A)."],formulas:[{title:"Secondary Metabolites Table",formula:"Lectins: Concanavalin A|Toxins: Abrin, Ricin|Alkaloids: Morphine, Codeine"}],neetImportantPoints:["Peptide bond connects amino acids (-CO-NH-); Glycosidic bond connects monosaccharides; Phosphodiester bond connects nucleotides."],commonConfusions:[{commonConfusion:"Confusing terms in Biomolecules - Primary & Secondary Metabolites.",correctFact:"Memorize exact NCERT examples and diagrams for Biomolecules - Primary & Secondary Metabolites.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Concanavalin A = Lectin, Lipids in acid-insoluble pool"]},pyqs:[]},"bio-enzymes-action-inhibition":{id:"bio-enzymes-action-inhibition",title:"Enzymes - Action Mechanism & Competitive Inhibition",chapterId:"biomolecules-bio",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Enzyme active site, activation energy lowering, V_max, K_m (Michaelis constant), competitive inhibition.",notes:{learn:["Enzymes lower the activation energy barrier for conversion of substrate into product without altering equilibrium constant.","Competitive Inhibition: Inhibitor closely resembles substrate in structure and competes for active site (e.g. Malonate inhibits Succinic dehydrogenase). V_max stays SAME, K_m INCREASES."],keyConcepts:["Enzymes lower the activation energy barrier for conversion of substrate into product without altering equilibrium constant."],formulas:[{title:"Competitive Inhibition Parameters",formula:"Competitive Inhibitor implies V_{max}|UNCHANGED, quad K_m|INCREASES"}],neetImportantPoints:["Co-factors: Prosthetic group (tightly bound organic e.g. Haem in peroxidase), Co-enzyme (transient organic e.g. NAD, NADP containing Niacin), Metal ions (Zn²⁺ in carboxypeptidase)."],commonConfusions:[{commonConfusion:"Confusing terms in Enzymes - Action Mechanism & Competitive Inhibition.",correctFact:"Memorize exact NCERT examples and diagrams for Enzymes - Action Mechanism & Competitive Inhibition.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Malonate inhibits Succinic dehydrogenase, Vmax same Km increases"]},pyqs:[]},"bio-cell-cycle-interphase":{id:"bio-cell-cycle-interphase",title:"Cell Cycle & Phases (G_1, S, G_2, M)",chapterId:"cell-cycle-division",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Interphase (G_1, S, G_2), G_0 resting phase, DNA replication timing, and Mitotic stages.",notes:{learn:["Interphase occupies > 95% of cell cycle duration. G1 phase (cell growth, protein synthesis); S phase (DNA REPLICATION occurs in nucleus, centriole duplicates in cytoplasm; chromosome number remains SAME 2n, DNA content doubles from 2C to 4C!).","G0 phase (Quiescent stage): Cells remain metabolically active but no longer proliferate unless called upon (e.g. Heart cells, Neurons)."],keyConcepts:["Interphase occupies > 95% of cell cycle duration. G1 phase (cell growth, protein synthesis); S phase (DNA REPLICATION occurs in nucleus, centriole duplicates in cytoplasm; chromosome number remains SAME 2n, DNA content doubles from 2C to 4C!)."],formulas:[{title:"S Phase DNA Content",formula:"In S Phase: DNA amount 2C to 4C, quad Chromosome number 2n to 2n|(Unchanged!)"}],neetImportantPoints:["Mitosis stages: Prophase -> Metaphase (chromosomes align at equatorial plate, best stage to study morphology) -> Anaphase (centromeres split, sister chromatids separate) -> Telophase."],commonConfusions:[{commonConfusion:"Confusing terms in Cell Cycle & Phases (G_1, S, G_2, M).",correctFact:"Memorize exact NCERT examples and diagrams for Cell Cycle & Phases (G_1, S, G_2, M).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["S phase = DNA doubles 2C to 4C, Chromosomes remain 2n"]},pyqs:[]},"bio-mitosis-meiosis":{id:"bio-mitosis-meiosis",title:"Meiosis I & II - Stages of Prophase I",chapterId:"cell-cycle-division",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"5 sub-stages of Prophase I (Leptotene, Zygotene, Pachytene, Diplotene, Diakinesis) and crossing over.",notes:{learn:["Prophase I Stages: Leptotene (chromosomes condense) -> Zygotene (synapsis of homologous chromosomes, Synaptonemal Complex forms, bivalents/tetrads) -> Pachytene (CROSSING OVER occurs via Recombinase enzyme) -> Diplotene (dissolution of synaptonemal complex, Chiasmata X-structures visible) -> Diakinesis (terminalisation of chiasmata).","Dictyotene stage: Oocytes of some vertebrates remain arrested in Diplotene for months or years."],keyConcepts:["Prophase I Stages: Leptotene (chromosomes condense) -> Zygotene (synapsis of homologous chromosomes, Synaptonemal Complex forms, bivalents/tetrads) -> Pachytene (CROSSING OVER occurs via Recombinase enzyme) -> Diplotene (dissolution of synaptonemal complex, Chiasmata X-structures visible) -> Diakinesis (terminalisation of chiasmata)."],formulas:[{title:"Prophase I Sub-stages Order",formula:"Leptotene to|Zygotene to|Pachytene (Crossing over) to|Diplotene (Chiasmata) to|Diakinesis"}],neetImportantPoints:["Meiosis produces 4 haploid daughter cells with genetic variations due to crossing over."],commonConfusions:[{commonConfusion:"Confusing terms in Meiosis I & II - Stages of Prophase I.",correctFact:"Memorize exact NCERT examples and diagrams for Meiosis I & II - Stages of Prophase I.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Pachytene = Crossing over, Diplotene = Chiasmata visible"]},pyqs:[]},"bio-photosynthetic-pigments-light-rxn":{id:"bio-photosynthetic-pigments-light-rxn",title:"Photosynthetic Pigments & Light Reactions",chapterId:"photosynthesis-higher-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Chlorophyll a, b, Carotenoids, Photosystem I & II, Z-scheme of electron transport, photolysis of water.",notes:{learn:["Photosystems: PS I (reaction center P700) and PS II (reaction center P680).","Light Reaction (Photochemical phase): Non-cyclic photophosphorylation involves both PS II and PS I, produces ATP and NADPH + H⁺, and evolves O2 by Splitting of Water (associated with PS II on inner membrane of thylakoid)."],keyConcepts:["Photosystems: PS I (reaction center P700) and PS II (reaction center P680)."],formulas:[{title:"Photolysis of Water Equation",formula:"2 H_2O xrightarrow{Mn^{2+}, Cl^-} 4 H^+ + 4 e^- + O_2"}],neetImportantPoints:["Cyclic photophosphorylation involves ONLY PS I, occurs in stroma lamellae (lacks PS II and NADP reductase), produces ONLY ATP (no NADPH or O2)."],commonConfusions:[{commonConfusion:"Confusing terms in Photosynthetic Pigments & Light Reactions.",correctFact:"Memorize exact NCERT examples and diagrams for Photosynthetic Pigments & Light Reactions.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["PS II splits water on inner thylakoid, Cyclic = PS I only"]},pyqs:[]},"bio-c3-c4-pathways":{id:"bio-c3-c4-pathways",title:"Calvin Cycle (C_3), Hatch-Slack (C_4) & Photorespiration",chapterId:"photosynthesis-higher-plants",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"RuBisCO carboxylase/oxygenase dual nature, C_3 vs C_4 anatomy (Kranz anatomy), and C_4 advantage.",notes:{learn:["C3 Cycle (Calvin Cycle): First stable product is 3-PGA (3 carbons). Primary CO2 acceptor is RuBP (5 carbons). Key enzyme RuBisCO.","C4 Pathway (Maize, Sugarcane, Sorghum): Possesses Kranz Anatomy (bundle sheath cells with large chloroplasts lacking grana). Primary CO2 acceptor in mesophyll is PEP (3 carbons) via PEP carboxylase. First stable product is OAA (4 carbons)."],keyConcepts:["C3 Cycle (Calvin Cycle): First stable product is 3-PGA (3 carbons). Primary CO2 acceptor is RuBP (5 carbons). Key enzyme RuBisCO."],formulas:[{title:"C3 vs C4 Key Differences",formula:"C_3: RuBP acceptor, 3-PGA product quad quad C_4: PEP acceptor in mesophyll, OAA product"}],neetImportantPoints:["Photorespiration (C2 cycle): Wasteful process in C3 plants when RuBisCO binds O2 at high temp/high O2. C4 plants LACK photorespiration entirely, making them more photosynthetic efficient!"],commonConfusions:[{commonConfusion:"Confusing terms in Calvin Cycle (C_3), Hatch-Slack (C_4) & Photorespiration.",correctFact:"Memorize exact NCERT examples and diagrams for Calvin Cycle (C_3), Hatch-Slack (C_4) & Photorespiration.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["C4 plants lack photorespiration and have Kranz anatomy"]},pyqs:[]},"bio-limiting-factors-photosynthesis":{id:"bio-limiting-factors-photosynthesis",title:"Factors Affecting Photosynthesis",chapterId:"photosynthesis-higher-plants",estimatedReadTimeMinutes:12,importanceWeight:"Core Concept",summary:"Blackman's Law of Limiting Factors, light saturation point, CO2 concentration effect.",notes:{learn:["Blackman's Law of Limiting Factors: If a chemical process is affected by more than one factor, its rate is determined by the factor nearest to its minimal value.","Light saturation occurs at 10% of full sunlight. Atmospheric CO2 concentration (0.03 - 0.04%) is major limiting factor for C3 plants."],keyConcepts:["Blackman's Law of Limiting Factors: If a chemical process is affected by more than one factor, its rate is determined by the factor nearest to its minimal value."],formulas:[{title:"Blackman's Law Statement",formula:"Rate is dictated by the factor present in sub-optimal / limiting quantity"}],neetImportantPoints:["C4 plants reach CO2 saturation at ~360 μL/L, whereas C3 plants require ~450 μL/L."],commonConfusions:[{commonConfusion:"Confusing terms in Factors Affecting Photosynthesis.",correctFact:"Memorize exact NCERT examples and diagrams for Factors Affecting Photosynthesis.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Blackman law of limiting factors, Light saturation at 10%"]},pyqs:[]},"bio-glycolysis-empp":{id:"bio-glycolysis-empp",title:"Glycolysis (EMP Pathway) & Fermentation",chapterId:"respiration-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"10-step glycolysis in cytoplasm, net ATP yield, anaerobic lactic acid and alcoholic fermentation.",notes:{learn:["Glycolysis (EMP Pathway) occurs in CYTOPLASM of all living organisms. Converts 1 molecule of Glucose (6C) into 2 molecules of Pyruvic Acid (3C) without using O2.","Net yield of Glycolysis: 2 ATP + 2 NADH + 2 H⁺ per glucose."],keyConcepts:["Glycolysis (EMP Pathway) occurs in CYTOPLASM of all living organisms. Converts 1 molecule of Glucose (6C) into 2 molecules of Pyruvic Acid (3C) without using O2."],formulas:[{title:"Glycolysis Key Enzyme",formula:"Rate limiting enzyme of Glycolysis is Phosphofructokinase (PFK)"}],neetImportantPoints:["Fermentation (Anaerobic): Alcoholic fermentation by yeast produces Ethanol + CO2 (catalysed by Pyruvate decarboxylase & Alcohol dehydrogenase); Lactic acid fermentation in muscle cells produces Lactic acid (catalysed by Lactate dehydrogenase)."],commonConfusions:[{commonConfusion:"Confusing terms in Glycolysis (EMP Pathway) & Fermentation.",correctFact:"Memorize exact NCERT examples and diagrams for Glycolysis (EMP Pathway) & Fermentation.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Glycolysis occurs in cytoplasm, Net 2 ATP + 2 NADH"]},pyqs:[]},"bio-krebs-cycle-ets":{id:"bio-krebs-cycle-ets",title:"TCA Cycle (Krebs Cycle) & Oxidative Phosphorylation",chapterId:"respiration-plants",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Link reaction (Acetyl-CoA), Krebs cycle in mitochondrial matrix, ETS complexes, ATP calculation.",notes:{learn:["Link Reaction (Mitochondrial matrix): Pyruvate + CoA + NAD⁺ -> Acetyl-CoA + CO2 + NADH + H⁺ (Pyruvate dehydrogenase).","Krebs Cycle: Primary CO2 acceptor Oxaloacetic Acid (OAA) + Acetyl-CoA -> Citric Acid (6C). 1 turn of Krebs cycle yields 3 NADH, 1 FADH2, 1 GTP."],keyConcepts:["Link Reaction (Mitochondrial matrix): Pyruvate + CoA + NAD⁺ -> Acetyl-CoA + CO2 + NADH + H⁺ (Pyruvate dehydrogenase)."],formulas:[{title:"ETS Complexes",formula:"Complex I: NADH Dehydrogenase|Complex IV: Cytochrome c Oxidase (Cyt a, a_3,|2 Cu centers)"}],neetImportantPoints:["Oxidative Phosphorylation occurs on inner mitochondrial membrane via Complex V (ATP Synthase: F0 channel + F1 headpiece). Total net ATP yield per glucose = 38 (or 36) ATP."],commonConfusions:[{commonConfusion:"Confusing terms in TCA Cycle (Krebs Cycle) & Oxidative Phosphorylation.",correctFact:"Memorize exact NCERT examples and diagrams for TCA Cycle (Krebs Cycle) & Oxidative Phosphorylation.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Krebs cycle in matrix, Complex IV contains Cyt a, a3 & Cu"]},pyqs:[]},"bio-plant-growth-phases-rates":{id:"bio-plant-growth-phases-rates",title:"Plant Growth, Growth Rates, Differentiation & Development",chapterId:"plant-growth-development",estimatedReadTimeMinutes:18,importanceWeight:"High Yield",summary:"Growth characteristics, phases (meristematic, elongation, maturation), growth rates (arithmetic & geometric), Sigmoid curve, absolute vs relative growth, differentiation, dedifferentiation, redifferentiation, development & plasticity.",notes:{learn:["Plant growth is open & indeterminate due to meristems (RAM/SAM for primary elongation; Cambium for secondary girth).","Arithmetic growth L_t = L_0 + rt (linear graph). Geometric growth W_1 = W_0 e^{rt} (Sigmoid S-curve: Lag, Log, Stationary).","Absolute growth rate = total growth/time. Relative growth rate (Efficiency Index) = growth/initial size. Leaf A (5->10) and Leaf B (50->55) have equal absolute growth (5 cm²) but Leaf A has 100% relative growth rate vs Leaf B (10%).","Differentiation = Tracheary elements (loss of protoplasm, lignified wall). Dedifferentiation = Parenchyma -> Interfascicular & Cork Cambium. Redifferentiation = Cambium -> Secondary xylem/phloem & Cork.","Plasticity: Heterophylly in Cotton, Coriander, Larkspur (developmental) and Buttercup (environmental)."],keyConcepts:["Indeterminate Open Growth","Arithmetic vs Geometric Growth Rates","Absolute vs Relative Growth Rate","Differentiation, Dedifferentiation, Redifferentiation","Plasticity and Heterophylly"],neetImportantPoints:["Maize root apical meristem produces > 17,500 new cells per hour. Watermelon cell size increases up to 3,500,000 times in volume.","Increased vacuolation is the hallmark of the Elongation phase. Thin cellulosic walls with rich protoplasm mark the Meristematic phase.","Arithmetic growth: L_t = L_0 + rt. Geometric growth: W_1 = W_0 e^{rt} (r is relative growth rate / efficiency index).","Tracheary element formation = Differentiation. Interfascicular and cork cambium formation = Dedifferentiation. Secondary tissues = Redifferentiation.","Developmental Heterophylly = Cotton, Coriander, Larkspur. Environmental Heterophylly = Buttercup."],commonConfusions:[{commonConfusion:"Confusing Absolute Growth Rate with Relative Growth Rate.",correctFact:"Absolute growth rate is net increase. Relative growth rate is increase per unit initial size.",whyItMattersForNEET:"Direct NCERT numerical comparison question."}],quickRevision:["Arithmetic: L_t = L_0 + rt. Geometric: W_1 = W_0 e^{rt}. Sigmoid curve: Lag -> Log -> Stationary. Differentiation -> Dedifferentiation -> Redifferentiation. Heterophylly in Cotton/Coriander/Larkspur (developmental) & Buttercup (environmental)."]}},"bio-plant-growth-regulators":{id:"bio-plant-growth-regulators",title:"Plant Growth Regulators (Auxin, GA, Cytokinin, Ethylene, ABA)",chapterId:"plant-growth-development",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Functions and applications of 5 major plant hormones.",notes:{learn:["Auxin (IAA, NAA, 2,4-D): Apical dominance, rooting in stem cuttings, selective weedicide (2,4-D kills dicot weeds).","Gibberellins (GA3): Bolting (internode elongation before flowering in rosette plants e.g. Cabbage/Beet), breaking seed dormancy, malting in brewing industry."],keyConcepts:["Auxin (IAA, NAA, 2,4-D): Apical dominance, rooting in stem cuttings, selective weedicide (2,4-D kills dicot weeds)."],formulas:[{title:"Cytokinins (Zeatin, Kinetin): Promotes cell division, overcomes apical dominance, delays leaf senescence (Richmond-Lang effect).",formula:"Ethylene & Abscisic Acid"}],neetImportantPoints:["Ethylene: Fruit ripening (Ethephon), triple response|ABA: Stress hormone, stomatal closure"],commonConfusions:[{commonConfusion:"Confusing terms in Plant Growth Regulators (Auxin, GA, Cytokinin, Ethylene, ABA).",correctFact:"Memorize exact NCERT examples and diagrams for Plant Growth Regulators (Auxin, GA, Cytokinin, Ethylene, ABA).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Abscisic Acid (ABA) is the Stress Hormone; induces stomatal closure during water deficit and promotes seed dormancy (antagonistic to Gibberellins)."]},pyqs:[]},"bio-photoperiodism-vernalization":{id:"bio-photoperiodism-vernalization",title:"Photoperiodism & Vernalization",chapterId:"plant-growth-development",estimatedReadTimeMinutes:12,importanceWeight:"High Yield",summary:"Short-day plants, long-day plants, day-neutral plants, florigen signal, and vernalization.",notes:{learn:["Photoperiodism: Response of plants to relative day/night length for flowering. Perceived by LEAVES via Phytochrome pigment.","Vernalization: Quantitative or qualitative dependence of flowering on low temperature exposure (cold treatment 1-7°C). Prevents precocious reproductive development late in growing season."],keyConcepts:["Photoperiodism: Response of plants to relative day/night length for flowering. Perceived by LEAVES via Phytochrome pigment."],formulas:[{title:"Site of Perception",formula:"Light perception site for flowering is LEAF, producing hypothetical signal Florigen"}],neetImportantPoints:["Biennial plants (e.g., Sugarbeet, Cabbage, Carrot) require cold treatment (vernalization) to flower in second year."],commonConfusions:[{commonConfusion:"Confusing terms in Photoperiodism & Vernalization.",correctFact:"Memorize exact NCERT examples and diagrams for Photoperiodism & Vernalization.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Leaves perceive light for flowering (Florigen)"]},pyqs:[]},"bio-blood-groups-coagulation":{id:"bio-blood-groups-coagulation",title:"Blood Groups & Coagulation Cascade",chapterId:"body-fluids-circulation",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"ABO blood grouping, Rh incompatibility (Erythroblastosis fetalis), blood clotting mechanism.",notes:{learn:["ABO blood grouping based on surface antigens A and B on RBCs. AB is universal recipient; O is universal donor.","Erythroblastosis Fetalis: Occurs when Rh-negative mother carries Rh-positive fetus. Severe anemia and jaundice in second Rh+ baby. Prevented by administering anti-Rh antibodies (RhOGAM) immediately after 1st delivery."],keyConcepts:["ABO blood grouping based on surface antigens A and B on RBCs. AB is universal recipient; O is universal donor."],formulas:[{title:"Blood Coagulation Cascade",formula:"Prothrombin xrightarrow{Thrombokinase, Ca^{2+}} Thrombin xrightarrow{} Fibrinogen to Fibrin clot"}],neetImportantPoints:["Calcium ions (Ca²⁺) play a crucial role in blood clotting cascade."],commonConfusions:[{commonConfusion:"Confusing terms in Blood Groups & Coagulation Cascade.",correctFact:"Memorize exact NCERT examples and diagrams for Blood Groups & Coagulation Cascade.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Rh- mother + Rh+ fetus = Erythroblastosis fetalis, Ca²⁺ essential for clotting"]},pyqs:[]},"bio-cardiac-cycle-ecg":{id:"bio-cardiac-cycle-ecg",title:"Cardiac Cycle, Heart Sounds & ECG",chapterId:"body-fluids-circulation",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Cardiac cycle phases (0.8 sec), stroke volume, cardiac output, heart sounds (LUB/DUB), ECG waves.",notes:{learn:["Cardiac Cycle duration = 0.8 seconds (at 72 beats/min). Stroke volume = 70 mL. Cardiac Output = Stroke Volume x Heart Rate ≈ 5 Liters/min.","Heart Sounds: 1st sound'LUB'due to closure of AV valves (Tricuspid & Bicuspid) at start of ventricular systole. 2nd sound'DUB'due to closure of Semilunar valves at end of ventricular systole."],keyConcepts:["Cardiac Cycle duration = 0.8 seconds (at 72 beats/min). Stroke volume = 70 mL. Cardiac Output = Stroke Volume x Heart Rate ≈ 5 Liters/min."],formulas:[{title:"ECG Waves Interpretation",formula:"P-wave: Atrial Depolarization|QRS-complex: Ventricular Depolarization|T-wave: Ventricular Repolarization"}],neetImportantPoints:["Number of QRS complexes in a given time interval determines the heart rate of an individual."],commonConfusions:[{commonConfusion:"Confusing terms in Cardiac Cycle, Heart Sounds & ECG.",correctFact:"Memorize exact NCERT examples and diagrams for Cardiac Cycle, Heart Sounds & ECG.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["LUB = AV valve closure, QRS = Ventricular depolarization"]},pyqs:[]},"bio-human-excretory-nephron":{id:"bio-human-excretory-nephron",title:"Human Excretory System & Nephron Structure",chapterId:"excretory-products",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Structure of kidney, cortical vs juxtamedullary nephrons, Malpighian corpuscle, PCT, Loop of Henle, DCT.",notes:{learn:["Human Excretory System: Pair of kidneys, ureters, urinary bladder, urethra.","Nephron is structural unit. Cortical nephrons (85%, short Loop of Henle); Juxtamedullary nephrons (15%, long Loop of Henle extending deep into medulla with Vasa Recta)."],keyConcepts:["Human Excretory System: Pair of kidneys, ureters, urinary bladder, urethra."],formulas:[{title:"Malpighian Corpuscle",formula:"Renal Corpuscle = Glomerulus (afferent/efferent arterioles) + Bowman's Capsule"}],neetImportantPoints:["PCT (Proximal Convoluted Tubule) is lined by simple cuboidal brush border epithelium; reabsorbs 70-80% of electrolytes and water."],commonConfusions:[{commonConfusion:"Confusing terms in Human Excretory System & Nephron Structure.",correctFact:"Memorize exact NCERT examples and diagrams for Human Excretory System & Nephron Structure.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["PCT reabsorbs 70-80% electrolytes, Vasa Recta in Juxtamedullary"]},pyqs:[]},"bio-urine-formation-counter-current":{id:"bio-urine-formation-counter-current",title:"Urine Formation & Counter-Current Mechanism",chapterId:"excretory-products",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Glomerular Filtration Rate (GFR), tubular reabsorption/secretion, Counter-Current multiplier, RAAS/ADH regulation.",notes:{learn:["GFR = 125 mL/min = 180 Liters/day (only ~1.5 L urine excreted, 99% reabsorbed).","Counter-Current Mechanism operates between Loop of Henle and Vasa Recta to create hyperosmolar medullary interstitium (1200 mOsmol/L) using NaCl and Urea, enabling production of concentrated urine."],keyConcepts:["GFR = 125 mL/min = 180 Liters/day (only ~1.5 L urine excreted, 99% reabsorbed)."],formulas:[{title:"RAAS Pathway",formula:"Low blood pressure implies JGA releases Renin to Angiotensinogen to Angiotensin II implies Aldosterone (Na^+|& H_2O reabsorption)"}],neetImportantPoints:["ADH (Vasopressin) from posterior pituitary acts on DCT/Collecting duct to facilitate water reabsorption during dehydration."],commonConfusions:[{commonConfusion:"Confusing terms in Urine Formation & Counter-Current Mechanism.",correctFact:"Memorize exact NCERT examples and diagrams for Urine Formation & Counter-Current Mechanism.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["GFR = 125 mL/min, Renin-Angiotensin system, ADH increases water reabsorption"]},pyqs:[]},"bio-muscle-contraction-sliding-filament":{id:"bio-muscle-contraction-sliding-filament",title:"Skeletal Muscle & Sliding Filament Theory",chapterId:"locomotion-movement",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Structure of sarcomere, actin/myosin filaments, troponin, tropomyosin, sliding filament mechanism.",notes:{learn:["Sarcomere is functional unit of contraction between two Z-lines. A-band (dark anisotropic, myosin); I-band (light isotropic, actin).","Sliding Filament Theory: Contraction triggered by Ca²⁺ release from Sarcoplasmic Reticulum -> Ca²⁺ binds to Troponin C -> unmasks active sites on Actin -> Myosin cross-bridge forms -> power stroke pulls Z-lines closer."],keyConcepts:["Sarcomere is functional unit of contraction between two Z-lines. A-band (dark anisotropic, myosin); I-band (light isotropic, actin)."],formulas:[{title:"Sarcomere Changes During Contraction",formula:"I-band SHORTENS, H-zone DISAPPEARS, A-band length REMAINS UNCHANGED"}],neetImportantPoints:["Troponin C binds Ca²⁺ ions during muscle contraction initiation."],commonConfusions:[{commonConfusion:"Confusing terms in Skeletal Muscle & Sliding Filament Theory.",correctFact:"Memorize exact NCERT examples and diagrams for Skeletal Muscle & Sliding Filament Theory.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["A-band length stays same, I-band shortens, Troponin C binds Ca²⁺"]},pyqs:[]},"bio-skeletal-system-joints":{id:"bio-skeletal-system-joints",title:"Human Skeleton, Joints & Disorders",chapterId:"locomotion-movement",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Axial (80) & appendicular (126) skeleton, fibrous/cartilaginous/synovial joints, myasthenia gravis, gout.",notes:{learn:["Human Skeleton has 206 bones. Skull, vertebral column (26), sternum (1), ribs (12 pairs = 24) form Axial skeleton (80 bones).","Joint Types: Fibrous (immovable e.g., sutures in skull); Cartilaginous (slightly movable e.g., between vertebrae); Synovial (freely movable e.g., Ball & Socket - shoulder/hip, Hinge - knee/elbow, Pivot - atlas/axis, Gliding - carpals, Saddle - thumb)."],keyConcepts:["Human Skeleton has 206 bones. Skull, vertebral column (26), sternum (1), ribs (12 pairs = 24) form Axial skeleton (80 bones)."],formulas:[{title:"Joint Examples",formula:"Pivot Joint: Atlas & Axis|Saddle Joint: Carpal & Metacarpal of thumb"}],neetImportantPoints:["Disorders: Myasthenia gravis (autoimmune disorder affecting neuromuscular junction); Tetany (rapid spasms due to low Ca²⁺ in body fluid); Gout (inflammation of joints due to uric acid crystals deposition)."],commonConfusions:[{commonConfusion:"Confusing terms in Human Skeleton, Joints & Disorders.",correctFact:"Memorize exact NCERT examples and diagrams for Human Skeleton, Joints & Disorders.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Pivot joint = Atlas & Axis, Gout = Uric acid accumulation"]},pyqs:[]},"bio-neuron-impulse-conduction":{id:"bio-neuron-impulse-conduction",title:"Neuron & Nerve Impulse Conduction",chapterId:"neural-control-coordination",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Resting membrane potential, action potential (depolarization/repolarization), synaptic transmission.",notes:{learn:["Resting Potential: Axonal membrane is more permeable to K⁺ than Na⁺ and impermeable to negatively charged proteins. Maintained by Na⁺/K⁺ ATPase pump (3 Na⁺ pumped OUT, 2 K⁺ IN). Resting potential ≈ -70 mV.","Action Potential: Stimulus opens voltage-gated Na⁺ channels -> rapid influx of Na⁺ causes DEPOLARIZATION (membrane potential turns positive to +30 mV). Repolarization follows as K⁺ channels open."],keyConcepts:["Resting Potential: Axonal membrane is more permeable to K⁺ than Na⁺ and impermeable to negatively charged proteins. Maintained by Na⁺/K⁺ ATPase pump (3 Na⁺ pumped OUT, 2 K⁺ IN). Resting potential ≈ -70 mV."],formulas:[{title:"Synaptic Transmission",formula:"Action potential arrives at axon terminal implies Ca^{2+}|influx implies Neurotransmitter (Acetylcholine) release into synaptic cleft"}],neetImportantPoints:["Saltatory conduction occurs in myelinated nerve fibers where action potential jumps from one Node of Ranvier to next."],commonConfusions:[{commonConfusion:"Confusing terms in Neuron & Nerve Impulse Conduction.",correctFact:"Memorize exact NCERT examples and diagrams for Neuron & Nerve Impulse Conduction.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Na⁺/K⁺ pump: 3 Na⁺ out, 2 K⁺ in; Depolarization via Na⁺ influx"]},pyqs:[]},"bio-human-brain-sensory-organs":{id:"bio-human-brain-sensory-organs",title:"Human Brain & Sensory Organs (Eye & Ear)",chapterId:"neural-control-coordination",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Forebrain, Midbrain, Hindbrain regions, structure of Eye (retina/rods/cones) and Ear (Organ of Corti).",notes:{learn:["Forebrain: Cerebrum (corpus callosum connects hemispheres), Thalamus, Hypothalamus (urges for eating/drinking, body temp regulation). Hindbrain: Cerebellum, Pons, Medulla oblongata (respiratory, cardiovascular, gastric reflexes).","Eye: Fovea centralis is point of maximum visual acuity (contains ONLY densely packed cones). Rods contain Rhodopsin (Vitamin A derivative) for twilight vision."],keyConcepts:["Forebrain: Cerebrum (corpus callosum connects hemispheres), Thalamus, Hypothalamus (urges for eating/drinking, body temp regulation). Hindbrain: Cerebellum, Pons, Medulla oblongata (respiratory, cardiovascular, gastric reflexes)."],formulas:[{title:"Ear Organ of Corti",formula:"Organ of Corti located on Basilar Membrane contains hair cells acting as auditory receptors"}],neetImportantPoints:["Eustachian tube connects middle ear cavity with pharynx to equalize pressure on both sides of eardrum."],commonConfusions:[{commonConfusion:"Confusing terms in Human Brain & Sensory Organs (Eye & Ear).",correctFact:"Memorize exact NCERT examples and diagrams for Human Brain & Sensory Organs (Eye & Ear).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Corpus callosum connects cerebral hemispheres, Fovea centralis = max vision acuity"]},pyqs:[]},"bio-endocrine-glands-hormones":{id:"bio-endocrine-glands-hormones",title:"Human Endocrine Glands & Hormones",chapterId:"chemical-coordination-integration",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Pituitary, Thyroid, Parathyroid, Adrenal, Pancreas, Gonads and related disorders.",notes:{learn:["Hypothalamus controls Pituitary. Neurohypophysis (Posterior pituitary) stores and releases Oxytocin (childbirth/milk ejection) and Vasopressin/ADH synthesized in hypothalamus.","Thyroid: T3 and T4 regulate BMR. Calcitonin (TCT) lowers blood Ca²⁺ levels. Parathyroid Hormone (PTH) INCREASES blood Ca²⁺ levels (hypercalcemic hormone, antagonistic to TCT)."],keyConcepts:["Hypothalamus controls Pituitary. Neurohypophysis (Posterior pituitary) stores and releases Oxytocin (childbirth/milk ejection) and Vasopressin/ADH synthesized in hypothalamus."],formulas:[{title:"Adrenal & Pancreas Hormones",formula:"Adrenal Cortex: Aldosterone (mineralo), Cortisol (gluco)|Pancreas: Insulin (beta-cells), Glucagon (alpha-cells)"}],neetImportantPoints:["Disorders: Cretinism (hypothyroidism in children); Exophthalmic goitre / Grave's disease (hyperthyroidism); Diabetes mellitus (insulin deficiency -> hyperglycemia & glucosuria); Addison's disease (hyposecretion of adrenal cortex hormones)."],commonConfusions:[{commonConfusion:"Confusing terms in Human Endocrine Glands & Hormones.",correctFact:"Memorize exact NCERT examples and diagrams for Human Endocrine Glands & Hormones.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["PTH increases blood Ca²⁺, Insulin lowers blood glucose"]},pyqs:[]},"bio-hormone-action-mechanism":{id:"bio-hormone-action-mechanism",title:"Mechanism of Hormone Action",chapterId:"chemical-coordination-integration",estimatedReadTimeMinutes:14,importanceWeight:"High Yield",summary:"Water-soluble (peptide/protein) vs Lipid-soluble (steroid/thyroid) hormone signaling.",notes:{learn:["Peptide / Protein Hormones (Insulin, Glucagon, Pituitary hormones, Epinephrine) bind to membrane-bound receptors and generate SECOND MESSENGERS (cAMP, IP3, Ca²⁺) to alter cell metabolism.","Steroid Hormones (Estrogen, Progesterone, Testosterone, Cortisol) and Iodothyronines (T3/T4) enter cell and bind to INTRA-CELLULAR receptors to regulate gene expression."],keyConcepts:["Peptide / Protein Hormones (Insulin, Glucagon, Pituitary hormones, Epinephrine) bind to membrane-bound receptors and generate SECOND MESSENGERS (cAMP, IP3, Ca²⁺) to alter cell metabolism."],formulas:[{title:"Second Messenger Types",formula:"Peptide Hormones generate second messengers: cAMP, IP_3,|Ca^{2+}"}],neetImportantPoints:["Steroid hormones do NOT generate second messengers; they interact directly with nuclear receptors."],commonConfusions:[{commonConfusion:"Confusing terms in Mechanism of Hormone Action.",correctFact:"Memorize exact NCERT examples and diagrams for Mechanism of Hormone Action.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Peptides = Membrane receptor + cAMP, Steroids = Intracellular receptor"]},pyqs:[]},"bio-microsporogenesis-megasporogenesis":{id:"bio-microsporogenesis-megasporogenesis",title:"Microsporogenesis & Megasporogenesis",chapterId:"sexual-repro-flowering-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Structure of anther, pollen grain wall (exine/intine), megasporogenesis, 7-celled 8-nucleate embryo sac.",notes:{learn:["Anther is bilobed, dithecous, tetrasporangiate. Tapetum is innermost nourishing layer (multinucleate). Pollen exine made of Sporopollenin (most resistant organic material known).","Female gametophyte (Embryo Sac) development is Monosporic: Functional megaspore undergoes 3 sequential mitotic divisions to form 7-celled, 8-nucleate embryo sac (3 antipodals, 2 synergids with filiform apparatus, 1 egg cell, 1 central cell with 2 polar nuclei)."],keyConcepts:["Anther is bilobed, dithecous, tetrasporangiate. Tapetum is innermost nourishing layer (multinucleate). Pollen exine made of Sporopollenin (most resistant organic material known)."],formulas:[{title:"Embryo Sac Structure",formula:"7-celled, 8-nucleate Embryo Sac (3 Antipodals + 2 Synergids + 1 Egg + 1 Central Cell with 2 Polar nuclei)"}],neetImportantPoints:["Filiform apparatus in synergids guides the entry of pollen tube into embryo sac."],commonConfusions:[{commonConfusion:"Confusing terms in Microsporogenesis & Megasporogenesis.",correctFact:"Memorize exact NCERT examples and diagrams for Microsporogenesis & Megasporogenesis.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Sporopollenin resists degradation, Embryo sac = 7 celled 8 nucleate"]},pyqs:[]},"bio-pollination-double-fertilization":{id:"bio-pollination-double-fertilization",title:"Pollination & Double Fertilization",chapterId:"sexual-repro-flowering-plants",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Autogamy, Geitonogamy, Xenogamy, outbreeding devices, and double fertilization mechanism.",notes:{learn:["Autogamy (self-pollination) prevented by Dichogamy, Self-incompatibility. Cleistogamous flowers (e.g., Viola, Oxalis, Commelina) never open and ensure 100% seed set without pollinators.","Double Fertilization (unique to Angiosperms): 1st Male gamete + Egg -> Zygote (2n) (Syngamy); 2nd Male gamete + 2 Polar Nuclei -> Primary Endosperm Nucleus (PEN, 3n) (Triple Fusion)."],keyConcepts:["Autogamy (self-pollination) prevented by Dichogamy, Self-incompatibility. Cleistogamous flowers (e.g., Viola, Oxalis, Commelina) never open and ensure 100% seed set without pollinators."],formulas:[{title:"Double Fertilization Formula",formula:"Syngamy (2n Zygote) + Triple Fusion (3n PEN) = Double Fertilization"}],neetImportantPoints:["Wind pollinated flowers (Anemophily) have lightweight non-sticky pollen and feathery stigma (e.g. Corn cob tassels)."],commonConfusions:[{commonConfusion:"Confusing terms in Pollination & Double Fertilization.",correctFact:"Memorize exact NCERT examples and diagrams for Pollination & Double Fertilization.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Cleistogamous = 100% autogamy, Triple fusion yields 3n PEN"]},pyqs:[]},"bio-endosperm-apomixis":{id:"bio-endosperm-apomixis",title:"Endosperm, Seed & Apomixis",chapterId:"sexual-repro-flowering-plants",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Free nuclear endosperm, albuminous vs non-albuminous seeds, apomixis, polyembryony.",notes:{learn:["Endosperm development precedes embryo development to ensure nutrition.","Non-albuminous (Ex-albuminous) seeds consume endosperm completely during development (Pea, Bean, Groundnut). Albuminous seeds retain endosperm (Castor, Sunflower, Maize, Wheat). Coconut water is free-nuclear endosperm."],keyConcepts:["Endosperm development precedes embryo development to ensure nutrition."],formulas:[{title:"Apomixis & Polyembryony",formula:"Apomixis: Seed formation WITHOUT fertilization (mimics sexual repro, e.g. Asteraceae, Grasses)"}],neetImportantPoints:["Polyembryony (occurrence of more than one embryo in a seed) is common in Citrus and Mango due to nucellar cells protruding into embryo sac."],commonConfusions:[{commonConfusion:"Confusing terms in Endosperm, Seed & Apomixis.",correctFact:"Memorize exact NCERT examples and diagrams for Endosperm, Seed & Apomixis.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Coconut water = Free nuclear endosperm, Apomixis = Seed without fertilization"]},pyqs:[]},"bio-male-female-repro-systems":{id:"bio-male-female-repro-systems",title:"Male & Female Human Reproductive Anatomy",chapterId:"human-reproduction",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Testes, seminiferous tubules, Leydig/Sertoli cells, female ovary, oviducts, uterus, mammary glands.",notes:{learn:["Male: Testes situated in scrotum (maintains temp 2-2.5°C lower than body temp for spermatogenesis). Leydig cells (interstitial) secrete Androgens (Testosterone). Sertoli cells provide nutrition to germ cells.","Sperm conduction pathway: Seminiferous tubules -> Rete testis -> Vasa efferentia -> Epididymis -> Vas deferens -> Ejaculatory duct -> Urethra."],keyConcepts:["Male: Testes situated in scrotum (maintains temp 2-2.5°C lower than body temp for spermatogenesis). Leydig cells (interstitial) secrete Androgens (Testosterone). Sertoli cells provide nutrition to germ cells."],formulas:[{title:"Female Reproductive Pathway",formula:"Ovary to|Infundibulum (Fimbriae) to|Ampulla (site of fertilization) to|Isthmus to|Uterus"}],neetImportantPoints:["Fertilization takes place at the Ampullary-isthmic junction / Ampulla of fallopian tube."],commonConfusions:[{commonConfusion:"Confusing terms in Male & Female Human Reproductive Anatomy.",correctFact:"Memorize exact NCERT examples and diagrams for Male & Female Human Reproductive Anatomy.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Sertoli cells = Nutrition, Leydig cells = Testosterone, Ampulla = Fertilization site"]},pyqs:[]},"bio-spermatogenesis-oogenesis":{id:"bio-spermatogenesis-oogenesis",title:"Spermatogenesis & Oogenesis",chapterId:"human-reproduction",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Hormonal control of gametogenesis, acrosome, polar bodies, meiotic arrest stages.",notes:{learn:["Spermatogenesis: Starts at puberty. Spermatogonia (2n) -> Primary spermatocyte (2n) -> Meiosis I -> 2 Secondary spermatocytes (n) -> Meiosis II -> 4 Spermatids (n) -> Spermiogenesis -> 4 Spermatozoa.","Oogenesis: Initiated during FETAL DEVELOPMENT. Primary oocyte arrests in Diplotene stage of Prophase I until puberty! Meiosis I yields 1 Secondary Oocyte (n) + 1st Polar Body. Meiosis II occurs ONLY UPON SPERM ENTRY in fallopian tube."],keyConcepts:["Spermatogenesis: Starts at puberty. Spermatogonia (2n) -> Primary spermatocyte (2n) -> Meiosis I -> 2 Secondary spermatocytes (n) -> Meiosis II -> 4 Spermatids (n) -> Spermiogenesis -> 4 Spermatozoa."],formulas:[{title:"Sperm Head Structure",formula:"Acrosome (cap filled with hyaluronidase / sperm lysins derived from Golgi)"}],neetImportantPoints:["LH surge triggers ovulation (release of secondary oocyte from mature Graafian follicle)."],commonConfusions:[{commonConfusion:"Confusing terms in Spermatogenesis & Oogenesis.",correctFact:"Memorize exact NCERT examples and diagrams for Spermatogenesis & Oogenesis.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Primary oocyte arrests in Diplotene, Oogenesis yields 1 functional ovum + polar bodies"]},pyqs:[]},"bio-menstrual-cycle-fertilization":{id:"bio-menstrual-cycle-fertilization",title:"Menstrual Cycle & Fertilization",chapterId:"human-reproduction",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Phases of menstrual cycle (Menstrual, Follicular/Proliferative, Ovulatory, Luteal/Secretory), Corpus Luteum.",notes:{learn:["Menstrual Cycle (28 days): Follicular phase driven by FSH/Estrogen -> Ovulation on day 14 triggered by LH Surge -> Luteal phase driven by Progesterone secreted by Corpus Luteum.","If fertilization occurs, Corpus Luteum persists due to hCG hormone; if not, Corpus Luteum degenerates into Corpus Albicans, leading to menstruation."],keyConcepts:["Menstrual Cycle (28 days): Follicular phase driven by FSH/Estrogen -> Ovulation on day 14 triggered by LH Surge -> Luteal phase driven by Progesterone secreted by Corpus Luteum."],formulas:[{title:"Menstrual Cycle Phases",formula:"Menstrual (1-5d) to|Follicular (6-13d) to|Ovulation (14d, LH surge) to|Luteal (15-28d, Progesterone)"}],neetImportantPoints:["Cortical reaction blocks polyspermy by altering zona pellucida membrane upon entry of first sperm."],commonConfusions:[{commonConfusion:"Confusing terms in Menstrual Cycle & Fertilization.",correctFact:"Memorize exact NCERT examples and diagrams for Menstrual Cycle & Fertilization.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["LH surge at Day 14 causes ovulation, Corpus luteum secretes Progesterone"]},pyqs:[]},"bio-pregnancy-parturition":{id:"bio-pregnancy-parturition",title:"Blastocyst Implantation, Placenta & Parturition",chapterId:"human-reproduction",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Blastocyst structure, hCG/hPL/Relaxin hormones, parturition (foetal ejection reflex), lactation.",notes:{learn:["Blastocyst consists of outer Trophoblast (attaches to endometrium) and Inner Cell Mass (gives rise to embryo).","Placenta acts as endocrine gland secreting hCG (human Chorionic Gonadotropin), hPL (human Placental Lactogen), Estrogen, Progesterone. Relaxin secreted by Ovary in late pregnancy."],keyConcepts:["Blastocyst consists of outer Trophoblast (attaches to endometrium) and Inner Cell Mass (gives rise to embryo)."],formulas:[{title:"Parturition Reflex",formula:"Foetal Ejection Reflex implies|Oxytocin release from posterior pituitary implies|Strong uterine contractions"}],neetImportantPoints:["Colostrum (first milk) is rich in IgA antibodies conferring passive immunity to newborn."],commonConfusions:[{commonConfusion:"Confusing terms in Blastocyst Implantation, Placenta & Parturition.",correctFact:"Memorize exact NCERT examples and diagrams for Blastocyst Implantation, Placenta & Parturition.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["hCG & hPL produced ONLY during pregnancy, Colostrum rich in IgA"]},pyqs:[]},"bio-contraception-methods":{id:"bio-contraception-methods",title:"Contraception Methods, MTP & Amniocentesis",chapterId:"reproductive-health",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Barrier, IUDs (Non-medicated, Copper-releasing, Hormone-releasing), Oral pills, Vasectomy, Tubectomy.",notes:{learn:["Intrauterine Devices (IUDs): Non-medicated (Lippes loop); Copper releasing (CuT, Cu7, Multiload 375 - Cu ions suppress sperm motility); Hormone releasing (Progestasert, LNG-20 - make uterus unsuitable for implantation).","Oral Contraceptive Pills (Saheli): Non-steroidal once-a-week pill developed by CDRI Lucknow."],keyConcepts:["Intrauterine Devices (IUDs): Non-medicated (Lippes loop); Copper releasing (CuT, Cu7, Multiload 375 - Cu ions suppress sperm motility); Hormone releasing (Progestasert, LNG-20 - make uterus unsuitable for implantation)."],formulas:[{title:"Surgical Sterilization",formula:"Vasectomy (cutting/tying Vas deferens in males)|Tubectomy (fallopian tubes in females)"}],neetImportantPoints:["Amniocentesis is sex-determination test based on chromosomal pattern of amniotic fluid cells; misused for female foeticide."],commonConfusions:[{commonConfusion:"Confusing terms in Contraception Methods, MTP & Amniocentesis.",correctFact:"Memorize exact NCERT examples and diagrams for Contraception Methods, MTP & Amniocentesis.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["CuT releases Cu ions to suppress motility, Saheli = once-a-week non-steroidal pill"]},pyqs:[]},"bio-stis-art-technologies":{id:"bio-stis-art-technologies",title:"STIs & Assisted Reproductive Technologies (ART)",chapterId:"reproductive-health",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"STIs (Gonorrhoea, Syphilis, Genital herpes, Hepatitis B, HIV) and ART techniques (IVF, ZIFT, GIFT, ICSI).",notes:{learn:["STIs: Hepatitis B, HIV, and Genital Herpes are NOT completely curable; others are curable if detected early.","Assisted Reproductive Technology (ART): IVF (In-vitro Fertilization) followed by ZIFT (Zygote Intra Fallopian Transfer up to 8 blastomeres) or IUT (Intra Uterine Transfer > 8 blastomeres)."],keyConcepts:["STIs: Hepatitis B, HIV, and Genital Herpes are NOT completely curable; others are curable if detected early."],formulas:[{title:"ART Techniques Comparison",formula:"ZIFT: Transfer le 8|blastomeres into Fallopian tube|GIFT: Transfer ovum into Fallopian tube"}],neetImportantPoints:["GIFT (Gamete Intra Fallopian Transfer): Used when female cannot produce ovum but can provide suitable environment. ICSI (Intra Cytoplasmic Sperm Injection): Sperm injected directly into ovum."],commonConfusions:[{commonConfusion:"Confusing terms in STIs & Assisted Reproductive Technologies (ART).",correctFact:"Memorize exact NCERT examples and diagrams for STIs & Assisted Reproductive Technologies (ART).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["ZIFT = embryo <= 8 cells in Fallopian tube, GIFT = gamete transfer"]},pyqs:[]},"bio-mendelian-genetics":{id:"bio-mendelian-genetics",title:"Mendel's Laws of Inheritance",chapterId:"principles-of-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Monohybrid cross (3:1 phenotypic, 1:2:1 genotypic), Dihybrid cross (9:3:3:1), Test cross.",notes:{learn:["Mendel selected Garden Pea (Pisum sativum) with 7 pairs of contrasting traits. Law of Segregation (Purity of Gametes) has NO exceptions!","Test Cross: Crossing unknown dominant phenotype individual (F1) with RECESSIVE parent to determine genotype (Monohybrid test cross ratio 1:1, Dihybrid 1:1:1:1)."],keyConcepts:["Mendel selected Garden Pea (Pisum sativum) with 7 pairs of contrasting traits. Law of Segregation (Purity of Gametes) has NO exceptions!"],formulas:[{title:"Mendelian Cross Ratios",formula:"F2 Monohybrid Phenotype 3:1|(Genotype 1:2:1)|Dihybrid Phenotype 9:3:3:1"}],neetImportantPoints:["Law of Independent Assortment applies to genes located on DIFFERENT chromosomes."],commonConfusions:[{commonConfusion:"Confusing terms in Mendel's Laws of Inheritance.",correctFact:"Memorize exact NCERT examples and diagrams for Mendel's Laws of Inheritance.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Monohybrid test cross ratio = 1:1, Segregation has no exceptions"]},pyqs:[]},"bio-non-mendelian-inheritance":{id:"bio-non-mendelian-inheritance",title:"Incomplete Dominance, Co-dominance & Multiple Alleles",chapterId:"principles-of-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Snapdragon flower color (1:2:1), ABO blood group co-dominance, Pleiotropy, Polygenic inheritance.",notes:{learn:["Incomplete Dominance (Snapdragon / Antirrhinum majus & Mirabilis jalapa): Red (RR) x White (rr) -> Pink (Rr). F2 phenotypic and genotypic ratio are IDENTICAL (1:2:1!).","Co-dominance & Multiple Alleles: ABO blood group governed by I gene with 3 alleles (I^A, I^B, i). Alleles I^A and I^B are co-dominant, both expressed in AB group."],keyConcepts:["Incomplete Dominance (Snapdragon / Antirrhinum majus & Mirabilis jalapa): Red (RR) x White (rr) -> Pink (Rr). F2 phenotypic and genotypic ratio are IDENTICAL (1:2:1!)."],formulas:[{title:"Incomplete Dominance Ratio",formula:"F2 Phenotypic and Genotypic ratios are both 1:2:1|in Antirrhinum"}],neetImportantPoints:["Polygenic Inheritance (Human skin color, height) controlled by 3 or more gene pairs; Pleiotropy (Phenylketonuria) single gene affects multiple phenotypic traits."],commonConfusions:[{commonConfusion:"Confusing terms in Incomplete Dominance, Co-dominance & Multiple Alleles.",correctFact:"Memorize exact NCERT examples and diagrams for Incomplete Dominance, Co-dominance & Multiple Alleles.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Incomplete dominance = 1:2:1 both ratios, ABO blood = Multiple alleles + Co-dominance"]},pyqs:[]},"bio-sex-determination-linkage":{id:"bio-sex-determination-linkage",title:"Sex Determination & Linkage/Recombination",chapterId:"principles-of-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Human XX-XY, Bird ZW-ZZ, Honeybee Haplodiploidy, Morgan's Drosophila linkage experiments.",notes:{learn:["Sex Determination: Humans (Male heterogamety XY); Birds (Female heterogamety ZW, females ZW, males ZZ); Honeybee (Haplodiploidy: Females 2n = 32 developed from fertilized egg, Males n = 16 developed via Parthenogenesis).","Morgan's Linkage Experiments on Drosophila melanogaster: Genes located close together on same chromosome show low recombination frequency and are LINKED."],keyConcepts:["Sex Determination: Humans (Male heterogamety XY); Birds (Female heterogamety ZW, females ZW, males ZZ); Honeybee (Haplodiploidy: Females 2n = 32 developed from fertilized egg, Males n = 16 developed via Parthenogenesis)."],formulas:[{title:"Haplodiploidy in Honeybee",formula:"Queen & Worker females (2n = 32)|Drone males (n = 16 via Parthenogenesis)"}],neetImportantPoints:["1% recombination frequency defined as 1 centimorgan (cM) or map unit (Morgan & Sturtevant)."],commonConfusions:[{commonConfusion:"Confusing terms in Sex Determination & Linkage/Recombination.",correctFact:"Memorize exact NCERT examples and diagrams for Sex Determination & Linkage/Recombination.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Birds = ZW female, Honeybee drones = Haploid male (Parthenogenesis)"]},pyqs:[]},"bio-genetic-disorders-human":{id:"bio-genetic-disorders-human",title:"Human Genetic Disorders (Mendelian & Chromosomal)",chapterId:"principles-of-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Haemophilia, Sickle-cell anemia, Phenylketonuria, Thalassemia, Down, Turner, Klinefelter syndromes.",notes:{learn:["Mendelian Disorders: Haemophilia (X-linked recessive); Sickle-cell Anemia (Autosomal recessive, GAG to GUG mutation in 6th codon of β-globin chain substituting Glutamic acid with Valine); Thalassemia (Autosomal recessive, quantitative defect in globin synthesis).","Chromosomal Disorders: Down's Syndrome (Trisomy 21, 2n+1 = 47); Klinefelter's Syndrome (44+XXY = 47, sterile male with gynecomastia); Turner's Syndrome (44+XO = 45, sterile female with webbed neck)."],keyConcepts:["Mendelian Disorders: Haemophilia (X-linked recessive); Sickle-cell Anemia (Autosomal recessive, GAG to GUG mutation in 6th codon of β-globin chain substituting Glutamic acid with Valine); Thalassemia (Autosomal recessive, quantitative defect in globin synthesis)."],formulas:[{title:"Sickle Cell Anemia Mutation",formula:"6th position of beta-chain: GAG (Glutamic acid) to|GUG (Valine)"}],neetImportantPoints:["Pedigree chart symbols: Solid symbol = Affected individual; Circle = Female; Square = Male."],commonConfusions:[{commonConfusion:"Confusing terms in Human Genetic Disorders (Mendelian & Chromosomal).",correctFact:"Memorize exact NCERT examples and diagrams for Human Genetic Disorders (Mendelian & Chromosomal).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Sickle cell = Glu to Val at 6th position, Down = Trisomy 21"]},pyqs:[]},"bio-dna-search-structure":{id:"bio-dna-search-structure",title:"Search for Genetic Material & DNA Double Helix",chapterId:"molecular-basis-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Griffith transformation, Avery-MacLeod-McCarty, Hershey-Chase experiment, Watson-Crick DNA model.",notes:{learn:["Griffith (1928) Transformation experiment with Streptococcus pneumoniae (S-strain virulent, R-strain avirulent).","Hershey & Chase (1952) unequivocally proved DNA is genetic material using radioactive ³⁵S (protein coat) and ³²P (DNA) with T2 bacteriophage."],keyConcepts:["Griffith (1928) Transformation experiment with Streptococcus pneumoniae (S-strain virulent, R-strain avirulent)."],formulas:[{title:"Watson-Crick Double Helix (1953): Anti-parallel strands (5'->3' and 3'->5'), pitch = 3.4 nm (34 Å), 10 base pairs per turn, distance between bp = 0.34 nm. Chargaff's Rule: [A] = [T] and [G] = [C] (A+G = T+C).",formula:"Hershey-Chase Isotope Marker"}],neetImportantPoints:["DNA marked with ^{32}P (P entered cell)|Protein marked with ^{35}S (S remained outside)"],commonConfusions:[{commonConfusion:"Confusing terms in Search for Genetic Material & DNA Double Helix.",correctFact:"Memorize exact NCERT examples and diagrams for Search for Genetic Material & DNA Double Helix.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["RNA was the first genetic material (ribozymes have catalytic capability)."]},pyqs:[]},"bio-dna-replication-enzymes":{id:"bio-dna-replication-enzymes",title:"DNA Replication & Meselson-Stahl Experiment",chapterId:"molecular-basis-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Meselson-Stahl experiment (^{15}N), replication fork, DNA Polymerase, Okazaki fragments.",notes:{learn:["Meselson & Stahl (1958) proved semi-conservative DNA replication in E. coli using heavy isotope ¹⁵N and CsCl density gradient centrifugation.","DNA Polymerase synthesizes DNA ONLY in 5' -> 3' direction. Leading strand is synthesized continuously; Lagging strand is synthesized discontinuously as Okazaki fragments joined by DNA Ligase."],keyConcepts:["Meselson & Stahl (1958) proved semi-conservative DNA replication in E. coli using heavy isotope ¹⁵N and CsCl density gradient centrifugation."],formulas:[{title:"Meselson-Stahl Centrifugation",formula:"CsCl density gradient centrifugation separates ^{15}N-^{15}N, ^{15}N-^{14}N, and ^{14}N-^{14}N DNA"}],neetImportantPoints:["Replication origin (ori) is specific sequence where replication initiates."],commonConfusions:[{commonConfusion:"Confusing terms in DNA Replication & Meselson-Stahl Experiment.",correctFact:"Memorize exact NCERT examples and diagrams for DNA Replication & Meselson-Stahl Experiment.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Meselson-Stahl = ¹⁵N CsCl gradient, DNA Polymerase works 5' -> 3'"]},pyqs:[]},"bio-transcription-genetic-code":{id:"bio-transcription-genetic-code",title:"Transcription & Features of Genetic Code",chapterId:"molecular-basis-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Transcription unit (Promoter, Structural gene, Terminator), mRNA processing, 64 codons properties.",notes:{learn:["Transcription Unit: Promoter at 5'-end of coding strand; Template strand is 3' -> 5'; Coding strand is 5' -> 3'.","Eukaryotic post-transcriptional modifications: Splicing (removes introns), Capping (methyl guanosine triphosphate at 5'-end), Tailing (poly-A tail ~200-300 adenylate residues at 3'-end)."],keyConcepts:["Transcription Unit: Promoter at 5'-end of coding strand; Template strand is 3' -> 5'; Coding strand is 5' -> 3'."],formulas:[{title:"Genetic Code Features",formula:"64 Codons (61 code for amino acids, 3 STOP codons: UAA, UAG, UGA). AUG codes for Methionine & acts as START codon."}],neetImportantPoints:["Genetic code is Degenerate (one amino acid coded by more than one codon), Unambiguous, Universal, and Commaless."],commonConfusions:[{commonConfusion:"Confusing terms in Transcription & Features of Genetic Code.",correctFact:"Memorize exact NCERT examples and diagrams for Transcription & Features of Genetic Code.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["AUG = Start codon + Methionine, UAA/UAG/UGA = Stop codons"]},pyqs:[]},"bio-translation-lac-operon":{id:"bio-translation-lac-operon",title:"Translation & Regulation of Gene Expression (Lac Operon)",chapterId:"molecular-basis-inheritance",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Ribosome, tRNA adapter, Lac Operon model (Jacob & Monod), Inducer (Lactose).",notes:{learn:["tRNA (Adapter molecule): Clover-leaf 2D structure, L-shaped 3D structure. Amino acid acceptor end at 3'-OH; Anticodon loop binds mRNA codon.","Lac Operon (Polycistronic in E. coli): Regulator gene i codes for Repressor. Structural genes: z (β-galactosidase), y (Permease), a (Transacetylase)."],keyConcepts:["tRNA (Adapter molecule): Clover-leaf 2D structure, L-shaped 3D structure. Amino acid acceptor end at 3'-OH; Anticodon loop binds mRNA codon."],formulas:[{title:"Lac Operon Induction",formula:"Lactose (Inducer) binds Repressor implies Inactivates repressor implies RNA Polymerase transcribes z, y, a"}],neetImportantPoints:["In absence of lactose, active repressor binds Operator region and prevents RNA polymerase from transcribing operon (Negative regulation)."],commonConfusions:[{commonConfusion:"Confusing terms in Translation & Regulation of Gene Expression (Lac Operon).",correctFact:"Memorize exact NCERT examples and diagrams for Translation & Regulation of Gene Expression (Lac Operon).",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["z = β-galactosidase, y = Permease, a = Transacetylase, Lactose = Inducer"]},pyqs:[]},"bio-hgp-dna-fingerprinting":{id:"bio-hgp-dna-fingerprinting",title:"Human Genome Project & DNA Fingerprinting",chapterId:"molecular-basis-inheritance",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"HGP goals/findings, VNTRs, Southern blotting, Alec Jeffreys methodology.",notes:{learn:["Human Genome Project (HGP): Mega project (1990-2003). Human genome contains ~3 x 10⁹ bp and ~30,000 genes. Chromosome 1 has highest number of genes (2968); Y chromosome has fewest (231). Less than 2% of genome codes for proteins.","DNA Fingerprinting (Alec Jeffreys): Relies on Satellite DNA showing high degree of Polymorphism in Variable Number of Tandem Repeats (VNTRs). Steps: Isolation -> Restriction digestion -> Gel electrophoresis -> Southern Blotting -> Hybridization with radioactive VNTR probe -> Autoradiography."],keyConcepts:["Human Genome Project (HGP): Mega project (1990-2003). Human genome contains ~3 x 10⁹ bp and ~30,000 genes. Chromosome 1 has highest number of genes (2968); Y chromosome has fewest (231). Less than 2% of genome codes for proteins."],formulas:[{title:"DNA Fingerprinting Probe",formula:"VNTRs (Variable Number of Tandem Repeats) used as radioactive probes in Southern Blotting"}],neetImportantPoints:["Single Nucleotide Polymorphisms (SNPs) occur at ~1.4 million locations in human genome."],commonConfusions:[{commonConfusion:"Confusing terms in Human Genome Project & DNA Fingerprinting.",correctFact:"Memorize exact NCERT examples and diagrams for Human Genome Project & DNA Fingerprinting.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Chromosome 1 has 2968 genes, VNTRs used in DNA fingerprinting"]},pyqs:[]},"bio-origin-of-life-proofs":{id:"bio-origin-of-life-proofs",title:"Origin of Life & Evidences for Evolution",chapterId:"evolution",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Miller-Urey experiment, Homologous vs Analogous organs, Adaptive Radiation.",notes:{learn:["Miller & Urey (1953) created spark discharge in CH4, NH3, H2, and H2O vapor at 800°C producing Amino Acids (Alanine, Glycine, Aspartic acid).","Homologous Organs (Divergent Evolution): Same origin/structure, different function (e.g., Forelimbs of Whale, Bat, Cheetah, Human; Thorns of Bougainvillea & Tendrils of Cucurbita). Analogous Organs (Convergent Evolution): Different origin, same function (e.g., Wings of Butterfly and Birds; Eye of Octopus and Mammals; Sweet Potato root & Potato stem)."],keyConcepts:["Miller & Urey (1953) created spark discharge in CH4, NH3, H2, and H2O vapor at 800°C producing Amino Acids (Alanine, Glycine, Aspartic acid)."],formulas:[{title:"Divergent vs Convergent",formula:"Homologous implies|Divergent Evolution|Analogous implies|Convergent Evolution"}],neetImportantPoints:["Adaptive Radiation: Evolution of different species starting from a point in a geographical area (e.g. Darwin's Finches in Galapagos Islands, Australian Marsupials)."],commonConfusions:[{commonConfusion:"Confusing terms in Origin of Life & Evidences for Evolution.",correctFact:"Memorize exact NCERT examples and diagrams for Origin of Life & Evidences for Evolution.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Miller used CH4, NH3, H2, H2O at 800°C, Homologous = Divergent"]},pyqs:[]},"bio-darwinism-natural-selection":{id:"bio-darwinism-natural-selection",title:"Darwinism & Types of Natural Selection",chapterId:"evolution",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Branching descent, natural selection, Industrial Melanism, types of selection curves.",notes:{learn:["Darwinian Theory based on two key concepts: Branching Descent and Natural Selection.","Industrial Melanism in Biston betularia moth (England): Before industrialization white-winged moths survived on lichen-covered trees; after industrialization dark/melanic moths survived on soot-covered trees (Anthropogenic evolution)."],keyConcepts:["Darwinian Theory based on two key concepts: Branching Descent and Natural Selection."],formulas:[{title:"3 Types of Natural Selection",formula:"1. Stabilizing (peak higher/narrower)|2. Directional (peak shifts)|3. Disruptive (two peaks form)"}],neetImportantPoints:["Antibiotic resistance in bacteria and pesticide resistance in insects are examples of natural selection by anthropogenic action."],commonConfusions:[{commonConfusion:"Confusing terms in Darwinism & Types of Natural Selection.",correctFact:"Memorize exact NCERT examples and diagrams for Darwinism & Types of Natural Selection.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Industrial Melanism in Biston betularia = Directional selection"]},pyqs:[]},"bio-hardy-weinberg-human-evolution":{id:"bio-hardy-weinberg-human-evolution",title:"Hardy-Weinberg Principle & Human Evolution",chapterId:"evolution",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"p² + 2pq + q² = 1 equation, factors disrupting equilibrium, human ancestor sequence.",notes:{learn:["Hardy-Weinberg Principle: Allele frequencies in a population remain constant (in equilibrium) from generation to generation unless disturbed by 5 factors: Gene migration/drift, Mutation, Recombination, Natural Selection.","Hardy-Weinberg Equation: p² + 2pq + q² = 1 (where p = frequency of allele A, q = frequency of allele a)."],keyConcepts:["Hardy-Weinberg Principle: Allele frequencies in a population remain constant (in equilibrium) from generation to generation unless disturbed by 5 factors: Gene migration/drift, Mutation, Recombination, Natural Selection."],formulas:[{title:"Human Evolution Sequence",formula:"Ramapithecus to|Australopithecus (3-4 mya) to|Homo habilis (650-800 cc) to|Homo erectus (900 cc) to|Neanderthal (1400 cc) to|Homo sapiens"}],neetImportantPoints:["Homo habilis was first hominid (brain capacity 650-800 cc, did not eat meat); Homo erectus (900 cc, ate meat); Neanderthal man (1400 cc, buried dead)."],commonConfusions:[{commonConfusion:"Confusing terms in Hardy-Weinberg Principle & Human Evolution.",correctFact:"Memorize exact NCERT examples and diagrams for Hardy-Weinberg Principle & Human Evolution.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Hardy-Weinberg p² + 2pq + q² = 1, Neanderthal brain = 1400 cc"]},pyqs:[]},"bio-common-human-diseases":{id:"bio-common-human-diseases",title:"Common Human Pathogenic Diseases",chapterId:"human-health-diseases",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Typhoid, Pneumonia, Common Cold, Malaria lifecycle, Amoebiasis, Ringworm, Filariasis.",notes:{learn:["Typhoid (Salmonella typhi): Confirmed by Widal Test; affects small intestine.","Pneumonia (Streptococcus pneumoniae, Haemophilus influenzae): Infects alveoli of lungs filling them with fluid. Common Cold (Rhinovirus): Infects nose and respiratory passage, BUT NOT LUNGS."],keyConcepts:["Typhoid (Salmonella typhi): Confirmed by Widal Test; affects small intestine."],formulas:[{title:"Malaria Lifecycle (Plasmodium): Infectious stage for human is SPOROZOITE (injected by female Anopheles mosquito). Sexual stage (Gametocytes) develop in human RBCs; Fertilization takes place in MOSQUITO GUT.",formula:"Malaria Infectious Stage"}],neetImportantPoints:["Infectious stage to humans: Sporozoite|Cause of fever: Haemozoin toxin"],commonConfusions:[{commonConfusion:"Confusing terms in Common Human Pathogenic Diseases.",correctFact:"Memorize exact NCERT examples and diagrams for Common Human Pathogenic Diseases.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Filariasis/Elephantiasis caused by Wuchereria bancrofti / W. malayi (transmitted by Culex mosquito). Ringworm caused by Microsporum, Trichophyton, Epidermophyton."]},pyqs:[]},"bio-immunity-types-vaccines":{id:"bio-immunity-types-vaccines",title:"Immunity, Antibody Structure & Vaccination",chapterId:"human-health-diseases",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Innate barriers, Acquired immunity (B-cells/T-cells), Antibody structure (H2L2), Autoimmunity.",notes:{learn:["Innate Immunity Barriers: Physical (Skin, Mucus); Physiological (Acid in stomach, Saliva, Tears); Cellular (PMNL-neutrophils, Monocytes, NK cells); Cytokine (Interferons secreted by virus-infected cells).","Antibody Molecule (H2L2): Consists of 2 heavy chains and 2 light chains linked by disulfide bonds. IgA in Colostrum; IgG crosses Placenta; IgE involved in Allergic reactions (histamine/serotonin from Mast cells)."],keyConcepts:["Innate Immunity Barriers: Physical (Skin, Mucus); Physiological (Acid in stomach, Saliva, Tears); Cellular (PMNL-neutrophils, Monocytes, NK cells); Cytokine (Interferons secreted by virus-infected cells)."],formulas:[{title:"Antibody Structure",formula:"H_2L_2|formula with Antigen binding sites at N-terminal"}],neetImportantPoints:["Autoimmune Disease: Immune system attacks self-cells (e.g., Rheumatoid Arthritis). Cell-mediated immunity (T-lymphocytes) is responsible for GRAFT REJECTION in organ transplants."],commonConfusions:[{commonConfusion:"Confusing terms in Immunity, Antibody Structure & Vaccination.",correctFact:"Memorize exact NCERT examples and diagrams for Immunity, Antibody Structure & Vaccination.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["IgA in Colostrum, IgE in Allergy, T-cells cause Graft Rejection"]},pyqs:[]},"bio-aids-cancer-drug-abuse":{id:"bio-aids-cancer-drug-abuse",title:"AIDS, Cancer & Drug Abuse",chapterId:"human-health-diseases",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"HIV replication in Helper T-cells, Cancer oncogenes/metastasis, Opioids/Cannabinoids/Cocaine.",notes:{learn:["AIDS (HIV retrovirus): Attacks Helper T-cells (CD4⁺) destroying immunity. Diagnostic test: ELISA. Treatment: Anti-retroviral drugs.","Cancer: Loss of Contact Inhibition. Malignant tumors show METASTASIS (cancer cells spread via blood to distant sites). Proto-oncogenes activated to Oncogenes. Detection: Biopsy, MRI, CT scan."],keyConcepts:["AIDS (HIV retrovirus): Attacks Helper T-cells (CD4⁺) destroying immunity. Diagnostic test: ELISA. Treatment: Anti-retroviral drugs."],formulas:[{title:"Plant Drug Sources",formula:"Opioids (Heroin/Morphine): Poppy plant (Papaver somniferum)|Cannabinoids: Cannabis sativa|Cocaine: Erythroxylum coca"}],neetImportantPoints:["Morphine is a potent sedative and painkiller useful for surgery patients."],commonConfusions:[{commonConfusion:"Confusing terms in AIDS, Cancer & Drug Abuse.",correctFact:"Memorize exact NCERT examples and diagrams for AIDS, Cancer & Drug Abuse.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["HIV attacks Helper T-cells, Cancer metastasis, Morphine from Poppy"]},pyqs:[]},"bio-microbes-household-industrial":{id:"bio-microbes-household-industrial",title:"Microbes in Household & Industrial Production",chapterId:"microbes-human-welfare",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"LAB in curd, Swiss cheese (Propionibacterium), Penicillin, Statins, Cyclosporin A, Streptokinase.",notes:{learn:["Household: Lactobacillus (LAB) converts milk to curd, increases Vitamin B12. Swiss cheese large holes due to CO2 produced by Propionibacterium sharmanii.","Bioactive Molecules: Cyclosporin A (immunosuppressive agent in organ transplant) produced by fungus Trichoderma polysporum."],keyConcepts:["Household: Lactobacillus (LAB) converts milk to curd, increases Vitamin B12. Swiss cheese large holes due to CO2 produced by Propionibacterium sharmanii."],formulas:[{title:"Statins (blood-cholesterol lowering agent) produced by yeast Monascus purpureus (inhibits cholesterol synthesis enzyme). Streptokinase (clot buster) produced by Streptococcus.",formula:"Microbial Bioactive Molecules"}],neetImportantPoints:["Cyclosporin A (Trichoderma polysporum)|Statins (Monascus purpureus)|Clot buster (Streptococcus)"],commonConfusions:[{commonConfusion:"Confusing terms in Microbes in Household & Industrial Production.",correctFact:"Memorize exact NCERT examples and diagrams for Microbes in Household & Industrial Production.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Alexander Fleming discovered Penicillium notatum antibiotic while working on Staphylococci bacteria."]},pyqs:[]},"bio-microbes-sewage-biocontrol":{id:"bio-microbes-sewage-biocontrol",title:"Microbes in Sewage Treatment & Biocontrol",chapterId:"microbes-human-welfare",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Primary vs Secondary sewage treatment, BOD, Biogas plant (Methanogens), Baculoviruses.",notes:{learn:["Sewage Treatment: Primary (physical filtration & sedimentation) -> Secondary / Biological (aerobic flocs consume organic matter -> REDUCES BOD). Activated sludge pumped into anaerobic sludge digester producing Biogas (CH4, H2S, CO2).","BOD (Biochemical Oxygen Demand) measures organic pollution in water. High BOD = High pollution!"],keyConcepts:["Sewage Treatment: Primary (physical filtration & sedimentation) -> Secondary / Biological (aerobic flocs consume organic matter -> REDUCES BOD). Activated sludge pumped into anaerobic sludge digester producing Biogas (CH4, H2S, CO2)."],formulas:[{title:"Biocontrol & Biofertilizers",formula:"Bt (Bacillus thuringiensis)|Trichoderma (fungus in root ecosystems)|Baculoviruses (Nucleopolyhedrovirus: species-specific, narrow spectrum)"}],neetImportantPoints:["Mycorrhiza (Glomus fungus) absorbs Phosphorus from soil for plants."],commonConfusions:[{commonConfusion:"Confusing terms in Microbes in Sewage Treatment & Biocontrol.",correctFact:"Memorize exact NCERT examples and diagrams for Microbes in Sewage Treatment & Biocontrol.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["BOD decreases during sewage treatment, Baculovirus = species specific"]},pyqs:[]},"bio-restriction-enzymes-vectors":{id:"bio-restriction-enzymes-vectors",title:"Recombinant DNA Tools - Restriction Enzymes & Vectors",chapterId:"biotech-principles",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Restriction endonucleases (EcoRI), palindromic sequences, pBR322 vector selectable markers.",notes:{learn:["Restriction Endonucleases (Molecular Scissors): Hind II was 1st discovered. EcoRI cuts DNA at palindromic sequence 5'-GAATTC-3' between G and A, producing sticky ends.","Cloning Vector pBR322: Contains ori, rop, selectable markers amp^R (ampicillin resistance) and tet^R (tetracycline resistance). Insertional Inactivation of β-galactosidase gene (lacZ) gives WHITE recombinant colonies and BLUE non-recombinant colonies in presence of chromogenic substrate (X-gal)."],keyConcepts:["Restriction Endonucleases (Molecular Scissors): Hind II was 1st discovered. EcoRI cuts DNA at palindromic sequence 5'-GAATTC-3' between G and A, producing sticky ends."],formulas:[{title:"EcoRI Recognition Palindromic Sequence",formula:"5'-G A A T T C-3' quad / quad 3'-C T T A A G-5'"}],neetImportantPoints:["Competent cells created by treating host bacteria with divalent cation like Calcium (Ca²⁺) followed by heat shock (42°C)."],commonConfusions:[{commonConfusion:"Confusing terms in Recombinant DNA Tools - Restriction Enzymes & Vectors.",correctFact:"Memorize exact NCERT examples and diagrams for Recombinant DNA Tools - Restriction Enzymes & Vectors.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["EcoRI cuts 5'-GAATTC-3', Insertional inactivation lacZ blue/white selection"]},pyqs:[]},"bio-pcr-rdna-process":{id:"bio-pcr-rdna-process",title:"Polymerase Chain Reaction (PCR) & rDNA Steps",chapterId:"biotech-principles",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"3 steps of PCR (Denaturation, Annealing, Extension), Taq Polymerase, downstream processing.",notes:{learn:["PCR Steps: 1. Denaturation (high temp 94°C separates DNA strands); 2. Annealing (55°C oligonucleotide primers bind); 3. Extension (72°C thermostable Taq Polymerase from Thermus aquaticus extends primers using dNTPs).","Amplification factor in PCR: 1 billion copies after ~30 cycles."],keyConcepts:["PCR Steps: 1. Denaturation (high temp 94°C separates DNA strands); 2. Annealing (55°C oligonucleotide primers bind); 3. Extension (72°C thermostable Taq Polymerase from Thermus aquaticus extends primers using dNTPs)."],formulas:[{title:"PCR 3 Steps",formula:"Denaturation (94^circC) to|Annealing (55^circC) to|Extension (72^circC, Taq Polymerase)"}],neetImportantPoints:["Downstream Processing involves separation and purification of recombinant product followed by quality testing before marketing."],commonConfusions:[{commonConfusion:"Confusing terms in Polymerase Chain Reaction (PCR) & rDNA Steps.",correctFact:"Memorize exact NCERT examples and diagrams for Polymerase Chain Reaction (PCR) & rDNA Steps.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Taq Polymerase from Thermus aquaticus, PCR 3 steps: Denaturation, Annealing, Extension"]},pyqs:[]},"bio-biotech-agriculture-bt":{id:"bio-biotech-agriculture-bt",title:"Biotechnology in Agriculture - Bt Crops & RNAi",chapterId:"biotech-applications",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Bt cotton (cry1Ac, cry2Ab, cry1Ab), RNA interference (RNAi) in Tobacco against Meloidogyne incognita.",notes:{learn:["Bt Cotton: Bacillus thuringiensis produces crystalline Cry protein protoxin. In alkaline pH of insect gut, protoxin converts to active toxin, binds midgut epithelial cells, creates pores, causing cell lysis and death.","Specific Cry genes: cry1Ac and cry2Ab control Cotton Bollworms; cry1Ab controls Corn Borer."],keyConcepts:["Bt Cotton: Bacillus thuringiensis produces crystalline Cry protein protoxin. In alkaline pH of insect gut, protoxin converts to active toxin, binds midgut epithelial cells, creates pores, causing cell lysis and death."],formulas:[{title:"RNA Interference (RNAi)",formula:"Silencing of specific mRNA using complementary dsRNA in Tobacco against nematode Meloidogyne incognita"}],neetImportantPoints:["RNA interference (RNAi) takes place in all eukaryotic organisms as a method of cellular defense."],commonConfusions:[{commonConfusion:"Confusing terms in Biotechnology in Agriculture - Bt Crops & RNAi.",correctFact:"Memorize exact NCERT examples and diagrams for Biotechnology in Agriculture - Bt Crops & RNAi.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["cry1Ac/cry2Ab = Cotton bollworm, cry1Ab = Corn borer, RNAi = Tobacco nematode"]},pyqs:[]},"bio-biotech-medicine-insulin":{id:"bio-biotech-medicine-insulin",title:"Biotechnology in Medicine - Humulin & Gene Therapy",chapterId:"biotech-applications",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Recombinant Human Insulin (Eli Lilly 1983), Gene Therapy for ADA deficiency, Transgenic animals.",notes:{learn:["Genetically Engineered Insulin (Humulin): Human insulin consists of Chain A (21 aa) and Chain B (30 aa) linked by disulfide bonds. In pro-insulin, extra C-peptide is present. Eli Lilly (1983) synthesized chain A and B separately in E. coli plasmid and linked them with disulfide bonds.","Gene Therapy: First clinical gene therapy (1990) given to 4-year-old girl with Adenosine Deaminase (ADA) deficiency using retroviral vector to introduce functional ADA cDNA into lymphocytes."],keyConcepts:["Genetically Engineered Insulin (Humulin): Human insulin consists of Chain A (21 aa) and Chain B (30 aa) linked by disulfide bonds. In pro-insulin, extra C-peptide is present. Eli Lilly (1983) synthesized chain A and B separately in E. coli plasmid and linked them with disulfide bonds."],formulas:[{title:"Genetically Engineered Insulin",formula:"Chain A + Chain B produced separately in E. coli implies Linked by Disulfide bonds"}],neetImportantPoints:["Transgenic Rosie cow (1997) produced human alpha-lactalbumin enriched milk (2.4 grams per liter)."],commonConfusions:[{commonConfusion:"Confusing terms in Biotechnology in Medicine - Humulin & Gene Therapy.",correctFact:"Memorize exact NCERT examples and diagrams for Biotechnology in Medicine - Humulin & Gene Therapy.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Humulin = Chain A & B linked by disulfide bonds, ADA gene therapy 1990"]},pyqs:[]},"bio-abiotic-factors-adaptations":{id:"bio-abiotic-factors-adaptations",title:"Abiotic Factors & Organism Adaptations",chapterId:"organism-populations",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Temperature (Eurythermal/Stenothermal), Salinity, Regulators vs Conformers, Allen's Rule.",notes:{learn:["Regulators maintain constant internal body temp/osmolarity (Homeostasis, e.g. Mammals, Birds). Conformers (99% animals, plants) change internal environment with ambient conditions.","Allen's Rule: Mammals from colder climates generally have SHORTER ears and limbs to minimize heat loss."],keyConcepts:["Regulators maintain constant internal body temp/osmolarity (Homeostasis, e.g. Mammals, Birds). Conformers (99% animals, plants) change internal environment with ambient conditions."],formulas:[{title:"Ecological Adaptations",formula:"Kangaroo rat in North American desert satisfies water need through internal fat oxidation"}],neetImportantPoints:["High Altitude Sickness (at > 3500 m) compensated by body by increasing RBC production, decreasing binding affinity of hemoglobin, and increasing breathing rate."],commonConfusions:[{commonConfusion:"Confusing terms in Abiotic Factors & Organism Adaptations.",correctFact:"Memorize exact NCERT examples and diagrams for Abiotic Factors & Organism Adaptations.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Allen's rule = shorter limbs in cold, High altitude = higher RBC production"]},pyqs:[]},"bio-population-growth-interactions":{id:"bio-population-growth-interactions",title:"Population Growth Curves & Species Interactions",chapterId:"organism-populations",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Exponential vs Logistic growth equation dN/dt = rN(K-N)/K, Predation, Competition, Mutualism, Parasitism.",notes:{learn:["Exponential Growth (Unlimited resources): dN/dt = r N (J-shaped curve). Logistic Growth (Limited resources): dN/dt = r N [(K - N) / K] (Sigmoid / S-shaped curve where K = Carrying capacity).","Species Interactions: Mutualism (+/+ e.g. Lichen, Mycorrhiza, Fig-Wasp); Competition (-/- Gause's Competitive Exclusion Principle); Predation (+/- e.g. Prickly pear cactus & moth); Parasitism (+/- Brood parasitism in Cuckoo/Koel); Commensalism (+/0 e.g. Cattle egret & cattle, Barnacle on whale, Orchid on mango); Amensalism (-/0 e.g. Penicillium inhibiting bacteria)."],keyConcepts:["Exponential Growth (Unlimited resources): dN/dt = r N (J-shaped curve). Logistic Growth (Limited resources): dN/dt = r N [(K - N) / K] (Sigmoid / S-shaped curve where K = Carrying capacity)."],formulas:[{title:"Logistic Growth Equation",formula:"dN / dt = r N ( (K - N) / K )"}],neetImportantPoints:["Gause's Competitive Exclusion Principle: Two closely related species competing for same limiting resources cannot co-exist indefinitely."],commonConfusions:[{commonConfusion:"Confusing terms in Population Growth Curves & Species Interactions.",correctFact:"Memorize exact NCERT examples and diagrams for Population Growth Curves & Species Interactions.",whyItMattersForNEET:"Direct NCERT line matching question in NEET UG."}],quickRevision:["Logistic growth dN/dt = rN(K-N)/K, Gause exclusion principle"]},pyqs:[]},"bio-ecosystem-structure-energy-flow":{id:"bio-ecosystem-structure-energy-flow",title:"Ecosystem Structure & Energy Flow (10% Law)",chapterId:"ecosystem",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"Abiotic/biotic components, Primary Productivity (GPP & NPP), 10% Energy Transfer Law.",notes:{learn:["Primary Productivity: Gross Primary Productivity (GPP) is the total rate of solar energy conversion into organic biomass. Net Primary Productivity (NPP) = GPP - R (respiratory loss). Annual NPP of entire biosphere is ~170 billion tons dry weight (Terrestrial = 115 billion tons on 30% area; Ocean = only 55 billion tons despite occupying 70% area due to light and mineral limitation).","PAR (Photosynthetically Active Radiation): Accounts for <50% of incident solar radiation. Plants capture only 2-10% of PAR (1-5% of total incident solar radiation) for photosynthesis.","Lindeman's 10% Law of Energy Transfer: In a grazing food chain, only ~10% of energy is transferred to each successive trophic level, with 90% lost as metabolic heat obeying the Second Law of Thermodynamics."],keyConcepts:["Net Primary Productivity: NPP = GPP - R (where R = respiratory loss by autotrophs).","10% Energy Transfer Law: Energy at trophic level n = 10% of Energy at trophic level (n-1).","PAR wavelength range is 400-700 nm, representing less than 50% of total solar radiation."],formulas:[{title:"Net Primary Productivity Formula",formula:"NPP = GPP - R"},{title:"Lindeman's 10% Energy Transfer Law",formula:"E_{(n+1)} = 0.10 times E_n"}],neetImportantPoints:["Oceans contribute only ~32% (55 billion tons) of global annual NPP despite covering 70% of Earth's surface.","Energy flow in an ecosystem is strictly UNIDIRECTIONAL (Sun -> Producers -> Consumers).","Detritus Food Chain (DFC) is the primary energy conduit in terrestrial systems; Grazing Food Chain (GFC) dominates in oceans."],commonConfusions:[{commonConfusion:"Thinking NPP is always greater than GPP.",correctFact:"NPP is ALWAYS strictly less than GPP because autotrophs consume a significant portion of GPP during cellular respiration (NPP = GPP - R).",whyItMattersForNEET:"Guaranteed high-yield NEET formula calculation and assertion-reason trap."},{commonConfusion:"Assuming energy flow in an ecosystem can be cyclical like nutrient cycles.",correctFact:"Nutrients cycle in loops (biogeochemical cycles), but energy flow is strictly UNIDIRECTIONAL and non-cyclic.",whyItMattersForNEET:"Tested repeatedly in NEET ecosystem fundamentals."}],quickRevision:["NPP = GPP - R","Global NPP = 170 billion tons (Land 115, Ocean 55)","PAR = 400-700 nm (<50% solar)","10% Law = 90% heat loss per tier"]},pyqs:[]},"bio-decomposition-ecological-pyramids":{id:"bio-decomposition-ecological-pyramids",title:"Decomposition & Ecological Pyramids",chapterId:"ecosystem",estimatedReadTimeMinutes:15,importanceWeight:"High Yield",summary:"5 steps of decomposition (Fragmentation, Leaching, Catabolism, Humification, Mineralisation), Ecological Pyramids.",notes:{learn:["Decomposition is an oxygen-requiring process breaking down organic detritus through 5 steps: 1. Fragmentation (detritivores e.g., earthworm pulverize detritus, increasing surface area); 2. Leaching (water-soluble inorganic nutrients seep into soil and precipitate); 3. Catabolism (bacterial and fungal extracellular enzymes degrade detritus); 4. Humification (formation of dark, amorphous, colloidal Humus that is highly resistant to microbial action); 5. Mineralisation (microbial release of inorganic ions from humus).","Fragmentation, Leaching, and Catabolism operate SIMULTANEOUSLY on fresh detritus. Decomposition is SLOW with Lignin/Chitin, and FAST with Nitrogen/Sugars. Cold temp and anaerobiosis inhibit decomposition.","Ecological Pyramids: Pyramid of Energy is ALWAYS UPRIGHT without exception. Pyramid of Biomass in sea is INVERTED (microscopic phytoplankton with rapid turnover support large biomass of zooplankton/fish). Pyramid of Numbers on a single tree with parasites is INVERTED.","Ecological Succession: Both Hydrarch (aquatic) and Xerarch (dry rock) successions progress to medium water conditions (MESIC conditions)."],keyConcepts:["5 Steps of Decomposition: Fragmentation, Leaching, Catabolism, Humification, Mineralisation.","Humus: Dark, amorphous, colloidal, microbial-resistant nutrient reservoir with very slow decomposition rate.","Pyramid of Energy: ALWAYS UPRIGHT in all ecosystems without exception.","Succession Endpoint: Both hydrarch and xerarch culminate in MESIC conditions."],formulas:[{title:"Pyramid Shapes Summary",formula:"Pyramid of Energy: ALWAYS UPRIGHT|Pyramid of Biomass in Sea: INVERTED|Pyramid of Numbers in Tree + Parasites: INVERTED"}],neetImportantPoints:["Fragmentation, Leaching, and Catabolism occur simultaneously on detritus.","Pyramid of Biomass in aquatic ecosystems is INVERTED.","71% of global carbon is dissolved in oceans; 4 × 10¹³ kg CO₂ is fixed annually by photosynthesis.","The Phosphorus cycle is sedimentary with rocks as primary reservoir and has no gaseous atmospheric release."],commonConfusions:[{commonConfusion:"Thinking decomposition steps occur strictly in isolated linear order.",correctFact:"Fragmentation, Leaching, and Catabolism operate SIMULTANEOUSLY on fresh detritus.",whyItMattersForNEET:"Repeatedly tested in NEET statement-verification questions."},{commonConfusion:"Assuming energy pyramid can be inverted in aquatic systems.",correctFact:"The BIOMASS pyramid is inverted in sea, but the ENERGY pyramid is ALWAYS UPRIGHT without exception.",whyItMattersForNEET:"One of the most frequent NEET traps across multiple exam years."}],quickRevision:["5 Decomposition steps: Frag, Leach, Catab, Humif, Miner","Humus = amorphous colloidal reservoir","Energy pyramid = ALWAYS upright","Biomass in sea = INVERTED","Succession = Mesic endpoint"]},pyqs:[]},"bio-biodiversity-patterns-loss":{id:"bio-biodiversity-patterns-loss",title:"Patterns of Biodiversity & Causes of Loss",chapterId:"biodiversity-conservation",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"Latitudinal gradients, Species-Area Relationship (Alexander von Humboldt), The Evil Quartet.",notes:{learn:["Biodiversity (Edward Wilson) encompasses Genetic Diversity (Rauwolfia reserpine variation, >50,000 rice strains, >1,000 mango varieties), Species Diversity (Western Ghats amphibians > Eastern Ghats), and Ecological Diversity (India deserts/rainforests/mangroves > Norway).","Global Species Diversity: Robert May estimated ~7 million species (IUCN recorded >1.5 million). Animals constitute >70% of species, plants <=22%, insects constitute >70% of all animals (7 out of 10 animals are insects). Fungi species exceed all fishes + amphibians + reptiles + mammals combined. India has 2.4% of land area and 8.1% of global species diversity (1 of 12 mega-diversity nations).","Latitudinal Gradient: Species richness decreases from equator to poles. Colombia (equator) has ~1,400 bird species; India has >1,200; New York (41°N) has 105; Greenland (71°N) has only 56. Tropical richness is driven by evolutionary time (undisturbed), constant/predictable climate (niche specialization), and high solar radiation.","Species-Area Relationship (Alexander von Humboldt): S = C A^Z (Rectangular hyperbola) and log S = log C + Z log A (Straight line). Slope Z is 0.1 to 0.2 for small regions, 0.6 to 1.2 for continents, and Z = 1.15 for frugivorous birds and mammals across tropical continental forests.","Ecosystem Stability: David Tilman (diversity reduces biomass fluctuation and increases productivity) and Paul Ehrlich (Rivet Popper hypothesis: wing rivets = keystone species).","The Evil Quartet (4 Causes of Loss): 1. Habitat loss & fragmentation (#1 cause, Amazon rainforest shrunk 14% to 6%); 2. Over-exploitation (Steller's sea cow, Passenger pigeon); 3. Alien species invasions (Nile perch in Lake Victoria wiped out >200 cichlid fishes; Parthenium, Lantana, Eichhornia, Clarias gariepinus); 4. Co-extinctions (obligate mutualisms like fig-wasp, host-parasite pairs)."],keyConcepts:["3 Levels of Biodiversity: Genetic, Species, Ecological.","Robert May's global species estimate = 7 million.","Latitudinal Gradient: Colombia (1,400 birds) -> NY (105) -> Greenland (56).","Species-Area Equation: log S = log C + Z log A (Z = 0.1-0.2 local, Z = 0.6-1.2 continental, Z = 1.15 frugivores).","The Evil Quartet: Habitat Loss (#1), Over-exploitation, Alien Invasions, Co-extinctions."],formulas:[{title:"Species-Area Relationship (Alexander von Humboldt)",formula:"S = C \\cdot A^Z \\iff \\log S = \\log C + Z \\log A"}],neetImportantPoints:["Insects make up >70% of all animal species; Fungi species exceed all vertebrate species combined.","India possesses 2.4% of world land area and 8.1% of global species diversity.","Amazon rainforest produces 20% of Earth's oxygen and is being cleared for soybean cultivation and cattle pasture.","Amphibians face the highest extinction threat (32%) among all vertebrate groups."],commonConfusions:[{commonConfusion:"Thinking Z-value in species-area relationship is a fixed universal constant.",correctFact:"Z is 0.1-0.2 for small regions, but steepens to 0.6-1.2 for entire continents (Z = 1.15 for frugivorous birds/mammals across tropical forests).",whyItMattersForNEET:"Examiners frequently test this numerical slope contrast."},{commonConfusion:"Assuming plants constitute the majority of global species.",correctFact:"Animals comprise >70% of all described species, while plants make up no more than 22%.",whyItMattersForNEET:"Tested directly from NCERT pie-chart data."}],quickRevision:["Genetic: Rauwolfia/rice/mango | Species: W. Ghats amphibians | Eco: India > Norway","Robert May: 7 million species | Animals >70% | Insects >70% animals | Fungi > all vertebrates","Latitudinal: Equator to Poles decrease (1400 -> 1200 -> 105 -> 56)","Humboldt: S = C A^Z | log S = log C + Z log A | Z = 0.1-0.2 (local), 1.15 (frugivores)","Evil Quartet: Habitat Loss (#1), Over-exploitation, Alien Invasions, Co-extinctions"]},pyqs:[]},"bio-insitu-exsitu-conservation":{id:"bio-insitu-exsitu-conservation",title:"In-situ & Ex-situ Conservation Strategies",chapterId:"biodiversity-conservation",estimatedReadTimeMinutes:16,importanceWeight:"High Yield",summary:"In-situ (Hotspots, National Parks, Biosphere reserves, Sacred Groves) vs Ex-situ (Botanical gardens, Cryopreservation).",notes:{learn:["In-situ Conservation (On-site): Protecting endangered species within natural habitats ('save the whole forest to save the tiger'). Includes: (1) 34 Biodiversity Hotspots globally (<2% land area, saves 30% extinctions; 3 Indian hotspots: Western Ghats-Sri Lanka, Indo-Burma, Himalaya); (2) 14 Biosphere Reserves with Core (no activity), Buffer (research/education), and Transition (settlements/cropping) zones; (3) 90 National Parks (strictly prohibited grazing and human exploitation); (4) 448 Wildlife Sanctuaries (regulated grazing allowed); (5) Sacred Groves (Khasi & Jaintia Hills in Meghalaya, Aravalli Hills in Rajasthan, Western Ghats in Karnataka/Maharashtra, Chanda & Bastar in Central India).","Ex-situ Conservation (Off-site): Protecting threatened species outside natural habitats in human-managed facilities. Includes: Zoological Parks (captive breeding), Botanical Gardens (living endangered flora), Wildlife Safari Parks, Seed Banks, Cryopreservation (-196°C in liquid nitrogen for gametes/embryos/tissues), In vitro fertilization (IVF), and Tissue Culture micropropagation.","International Conventions: (1) The Earth Summit (Convention on Biological Diversity) held in Rio de Janeiro, Brazil in 1992 for conservation and sustainable use of biodiversity; (2) World Summit on Sustainable Development held in Johannesburg, South Africa in 2002 where 190 countries committed to reduce biodiversity loss rate by 2010.","Red Data Book (IUCN): Catalogs extinction risk categories (Extinct, Extinct in the Wild, Critically Endangered, Endangered, Vulnerable)."],keyConcepts:["In-situ: Hotspots (34), Biosphere Reserves (14), National Parks (90), Sanctuaries (448), Sacred Groves.","Ex-situ: Zoos, Botanical Gardens, Safari Parks, Cryopreservation (-196°C in liquid N₂), Seed Banks, IVF.","Biosphere Reserve Zonation: Core -> Buffer -> Transition.","Sacred Groves in Meghalaya (Khasi & Jaintia Hills) are the last refuge for many rare/threatened plants.","Earth Summit (Rio 1992) vs. World Summit (Johannesburg 2002)."],formulas:[{title:"Cryopreservation Parameter",formula:"\\text{Liquid Nitrogen Storage at } -196^\\circ\\text{C} \\text{ (77 K)}"}],neetImportantPoints:["Sacred Groves are strictly IN-SITU conservation, NOT ex-situ.","Wildlife Sanctuaries are in-situ; Wildlife Safari Parks are ex-situ.","Hotspots cover <2% of Earth's land area but strict protection could reduce mass extinction by ~30%.","Grazing is strictly prohibited in National Parks, but regulated grazing is permitted in Wildlife Sanctuaries.","Cryopreservation stores biological germplasm at -196°C in liquid nitrogen."],commonConfusions:[{commonConfusion:"Classifying Sacred Groves as Ex-situ conservation.",correctFact:"Sacred Groves are strictly IN-SITU conservation because species are protected in their natural habitat by indigenous tribal traditions.",whyItMattersForNEET:"One of the most frequently repeated classification traps in NEET."},{commonConfusion:"Confusing Wildlife Sanctuaries (in-situ) with Wildlife Safari Parks (ex-situ).",correctFact:"Wildlife Sanctuaries are natural in-situ reserves; Wildlife Safari Parks are off-site ex-situ enclosures.",whyItMattersForNEET:"Direct option elimination trap in NEET UG."}],quickRevision:["In-situ: Hotspots (34, 3 in India), Biosphere (14), Parks (90), Sanctuaries (448), Sacred Groves","Ex-situ: Zoos, Botanical Gardens, Safari Parks, Seed Banks, Cryopreservation (-196°C)","Biosphere Zones: Core (0 activity) -> Buffer (research) -> Transition (settlements)","Sacred Groves: Khasi & Jaintia (Meghalaya), Aravalli (Rajasthan), W. Ghats, Bastar","Conventions: Earth Summit (Rio 1992) | World Summit (Johannesburg 2002)"]},pyqs:[]}};
